window.BCCT_DRUG_PACKAGE=window.BCCT_DRUG_PACKAGE||{drugs:[]};
window.BCCT_DRUG_PACKAGE.drugs.push(...[{"name":"Nhân sâm","aliases":["Panax ginseng","ginseng","hồng sâm"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ giảm mệt mỏi, suy nhược và cải thiện khả năng thích nghi với stress; bằng chứng thay đổi theo chế phẩm.","main":"Ginsenosid có tác động điều hòa thần kinh–nội tiết, miễn dịch và chuyển hóa; không thay thế điều trị nguyên nhân.","contraindications":"Tránh khi dị ứng; thận trọng ở mất ngủ, rối loạn nhịp, tăng huyết áp chưa kiểm soát, thai kỳ và bệnh tự miễn.","side":"Mất ngủ, kích thích, đau đầu, rối loạn tiêu hóa; hiếm gặp phản ứng dị ứng.","interactions":"Có thể ảnh hưởng INR/thuốc chống đông, đường huyết, huyết áp, thuốc kích thích và ức chế miễn dịch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Nh%C3%A2n%20s%C3%A2m"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Nh%C3%A2n%20s%C3%A2m%20medicinal%20herb"}]},{"name":"Tam thất","aliases":["Panax notoginseng","tam thất bắc"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng theo y học cổ truyền để hỗ trợ cầm máu, giảm đau do ứ huyết và phục hồi sau chấn thương; dữ liệu hiện đại chủ yếu về tuần hoàn.","main":"Saponin notoginsenosid có tác động lên tiểu cầu, vi tuần hoàn và phản ứng viêm.","contraindications":"Tránh khi đang chảy máu chưa kiểm soát, trước phẫu thuật, thai kỳ hoặc dùng thuốc chống đông/kháng kết tập tiểu cầu nếu chưa được đánh giá.","side":"Buồn nôn, khô miệng, chóng mặt, phát ban; có thể làm tăng nguy cơ chảy máu.","interactions":"Tăng nguy cơ chảy máu với warfarin, acenocoumarol, heparin, aspirin, clopidogrel và NSAID.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Tam%20th%E1%BA%A5t"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Tam%20th%E1%BA%A5t%20medicinal%20herb"}]},{"name":"Đinh lăng","aliases":["Polyscias fruticosa","cây gỏi cá"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian để hỗ trợ ăn ngủ, giảm mệt mỏi và lợi sữa; bằng chứng lâm sàng còn hạn chế.","main":"Saponin và polyacetylen có hoạt tính chống oxy hóa và điều hòa thần kinh trong nghiên cứu tiền lâm sàng.","contraindications":"Tránh dùng liều cao hoặc kéo dài ở thai kỳ, cho con bú khi chưa có tư vấn; thận trọng ở người dùng thuốc an thần.","side":"Có thể buồn ngủ, chóng mặt, rối loạn tiêu hóa; quá liều có thể gây mệt hoặc rối loạn nhịp.","interactions":"Có thể cộng hợp với thuốc an thần và thuốc hạ huyết áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90inh%20l%C4%83ng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90inh%20l%C4%83ng%20medicinal%20herb"}]},{"name":"Bạch quả","aliases":["Ginkgo biloba","ginkgo"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ triệu chứng suy giảm nhận thức hoặc tuần hoàn ngoại biên ở một số người; không dùng để điều trị cấp cứu đột quỵ.","main":"Flavonoid và terpene lacton có tác động chống oxy hóa, vi tuần hoàn và yếu tố hoạt hóa tiểu cầu.","contraindications":"Tránh ở người đang chảy máu, trước phẫu thuật, động kinh không kiểm soát hoặc dùng nhiều thuốc chống đông/kháng tiểu cầu.","side":"Đau đầu, chóng mặt, rối loạn tiêu hóa, dị ứng; nguy cơ chảy máu tăng.","interactions":"Tương tác với thuốc chống đông/kháng tiểu cầu, NSAID và thuốc làm giảm ngưỡng co giật.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BA%A1ch%20qu%E1%BA%A3"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BA%A1ch%20qu%E1%BA%A3%20medicinal%20herb"}]},{"name":"Nghệ","aliases":["Curcuma longa","curcumin","nghệ vàng"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ triệu chứng khó tiêu, viêm nhẹ và đau xương khớp; hiệu quả phụ thuộc chế phẩm và sinh khả dụng.","main":"Curcuminoid điều hòa nhiều đường tín hiệu viêm và chống oxy hóa.","contraindications":"Tránh khi tắc mật, sỏi mật có triệu chứng, chảy máu hoặc trước phẫu thuật; thận trọng thai kỳ và bệnh gan.","side":"Đầy bụng, tiêu chảy, buồn nôn; hiếm gặp tổn thương gan do chế phẩm curcumin đậm đặc.","interactions":"Có thể tăng chảy máu với thuốc chống đông/kháng tiểu cầu và ảnh hưởng thuốc hạ đường huyết.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ngh%E1%BB%87"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ngh%E1%BB%87%20medicinal%20herb"}]},{"name":"Gừng","aliases":["Zingiber officinale","ginger","sinh khương","can khương"],"category":"Dược liệu/Thuốc Nam","indications":"Giảm buồn nôn, say tàu xe và khó tiêu; có thể hỗ trợ đau bụng kinh.","main":"Gingerol và shogaol tác động lên nhu động tiêu hóa, thụ thể serotonin và phản ứng viêm.","contraindications":"Thận trọng khi chảy máu, sỏi mật, dùng chống đông hoặc trước phẫu thuật; liều thực phẩm thường an toàn.","side":"Ợ nóng, kích ứng miệng, tiêu chảy; liều cao có thể tăng chảy máu.","interactions":"Có thể cộng hợp thuốc chống đông/kháng tiểu cầu và thuốc hạ đường huyết.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=G%E1%BB%ABng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=G%E1%BB%ABng%20medicinal%20herb"}]},{"name":"Tỏi","aliases":["Allium sativum","garlic"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ giảm nhẹ huyết áp và lipid máu; không thay thế thuốc tim mạch đã được kê.","main":"Hợp chất lưu huỳnh như allicin ảnh hưởng tổng hợp cholesterol, giãn mạch và chức năng tiểu cầu.","contraindications":"Tránh liều bổ sung cao khi đang chảy máu, trước phẫu thuật hoặc dùng chống đông.","side":"Mùi cơ thể, ợ nóng, đau bụng; có thể gây chảy máu và dị ứng.","interactions":"Tăng nguy cơ chảy máu; có thể ảnh hưởng thuốc HIV và thuốc hạ áp/hạ đường huyết.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=T%E1%BB%8Fi"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=T%E1%BB%8Fi%20medicinal%20herb"}]},{"name":"Cam thảo","aliases":["Glycyrrhiza glabra","licorice","cam thảo bắc"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong một số bài thuốc để điều hòa, giảm ho và kích ứng niêm mạc; không nên dùng kéo dài liều cao.","main":"Glycyrrhizin ức chế chuyển hóa cortisol, gây tác dụng giống mineralocorticoid.","contraindications":"Tránh ở tăng huyết áp, suy tim, hạ kali, bệnh thận, thai kỳ hoặc dùng lợi tiểu/digoxin.","side":"Phù, tăng huyết áp, hạ kali, yếu cơ, rối loạn nhịp khi dùng nhiều hoặc kéo dài.","interactions":"Tương tác quan trọng với lợi tiểu, digoxin, corticosteroid, thuốc hạ áp và thuốc gây hạ kali.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Cam%20th%E1%BA%A3o"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Cam%20th%E1%BA%A3o%20medicinal%20herb"}]},{"name":"Hoàng kỳ","aliases":["Astragalus membranaceus","astragalus"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền để hỗ trợ suy nhược, ra mồ hôi và phục hồi; bằng chứng lâm sàng còn không đồng nhất.","main":"Polysaccharid và saponin có hoạt tính điều hòa miễn dịch và chống oxy hóa trong nghiên cứu.","contraindications":"Thận trọng bệnh tự miễn, sau ghép tạng, dùng thuốc ức chế miễn dịch, thai kỳ.","side":"Rối loạn tiêu hóa, phát ban; có thể thay đổi đáp ứng miễn dịch.","interactions":"Có thể đối kháng thuốc ức chế miễn dịch và ảnh hưởng đường huyết/huyết áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ho%C3%A0ng%20k%E1%BB%B3"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ho%C3%A0ng%20k%E1%BB%B3%20medicinal%20herb"}]},{"name":"Đương quy","aliases":["Angelica sinensis","dong quai"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong y học cổ truyền cho đau bụng kinh, kinh không đều và chứng huyết hư; bằng chứng hiện đại hạn chế.","main":"Coumarin, acid ferulic và tinh dầu có tác động lên mạch máu và cơ trơn.","contraindications":"Tránh khi đang chảy máu, rong kinh nhiều, ung thư nhạy cảm hormon, thai kỳ hoặc dùng chống đông.","side":"Đau đầu, rối loạn tiêu hóa, nhạy cảm ánh sáng, tăng chảy máu.","interactions":"Tăng nguy cơ chảy máu với warfarin/acenocoumarol, aspirin, clopidogrel và NSAID.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90%C6%B0%C6%A1ng%20quy"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90%C6%B0%C6%A1ng%20quy%20medicinal%20herb"}]},{"name":"Kỷ tử","aliases":["Lycium barbarum","goji berry","câu kỷ tử"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng làm thực phẩm và thuốc bổ; có thể hỗ trợ dinh dưỡng và chống oxy hóa nhưng không thay thế điều trị mắt/gan.","main":"Polysaccharid, carotenoid và zeaxanthin có hoạt tính chống oxy hóa.","contraindications":"Thận trọng khi dùng warfarin, thuốc hạ đường huyết/hạ áp hoặc dị ứng họ Cà.","side":"Rối loạn tiêu hóa, dị ứng; đã có báo cáo tăng INR.","interactions":"Có thể làm tăng INR và cộng hợp thuốc hạ đường huyết/hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=K%E1%BB%B7%20t%E1%BB%AD"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=K%E1%BB%B7%20t%E1%BB%AD%20medicinal%20herb"}]},{"name":"Hà thủ ô đỏ","aliases":["Fallopia multiflora","Polygonum multiflorum","he shou wu"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho tóc bạc sớm và suy nhược; chưa có bằng chứng chắc chắn cho mọc tóc.","main":"Anthraquinon và stilben có hoạt tính sinh học nhưng cũng liên quan độc tính gan.","contraindications":"Tránh ở bệnh gan, men gan tăng, thai kỳ, cho con bú hoặc dùng thuốc độc gan.","side":"Có thể gây tiêu chảy, đau bụng và tổn thương gan nặng.","interactions":"Tăng nguy cơ độc gan khi phối hợp rượu, paracetamol liều cao, isoniazid và thuốc độc gan khác.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=H%C3%A0%20th%E1%BB%A7%20%C3%B4%20%C4%91%E1%BB%8F"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=H%C3%A0%20th%E1%BB%A7%20%C3%B4%20%C4%91%E1%BB%8F%20medicinal%20herb"}]},{"name":"Diệp hạ châu","aliases":["Phyllanthus amarus","Phyllanthus urinaria","chó đẻ răng cưa"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian hỗ trợ bệnh gan và lợi tiểu; không thay thế thuốc điều trị viêm gan virus.","main":"Lignan và polyphenol có hoạt tính chống oxy hóa và kháng virus trong nghiên cứu tiền lâm sàng.","contraindications":"Thận trọng thai kỳ, hạ đường huyết, hạ huyết áp hoặc bệnh gan nặng chưa rõ nguyên nhân.","side":"Đau bụng, tiêu chảy, hạ đường huyết/huyết áp ở người nhạy cảm.","interactions":"Có thể cộng hợp thuốc hạ đường huyết, hạ áp và lợi tiểu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Di%E1%BB%87p%20h%E1%BA%A1%20ch%C3%A2u"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Di%E1%BB%87p%20h%E1%BA%A1%20ch%C3%A2u%20medicinal%20herb"}]},{"name":"Cà gai leo","aliases":["Solanum procumbens","Solanum hainanense"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong Nam dược để hỗ trợ chức năng gan và triệu chứng do rượu; bằng chứng lâm sàng còn giới hạn.","main":"Glycoalkaloid và flavonoid có tác động bảo vệ gan trong nghiên cứu tiền lâm sàng.","contraindications":"Tránh khi dị ứng họ Cà; thận trọng thai kỳ, trẻ nhỏ và bệnh gan cấp chưa chẩn đoán.","side":"Có thể rối loạn tiêu hóa hoặc dị ứng; dữ liệu an toàn dài hạn còn ít.","interactions":"Chưa xác định đầy đủ; thận trọng khi dùng cùng thuốc chuyển hóa qua gan.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=C%C3%A0%20gai%20leo"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=C%C3%A0%20gai%20leo%20medicinal%20herb"}]},{"name":"Atisô","aliases":["Cynara scolymus","artichoke"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ khó tiêu, đầy bụng và giảm nhẹ cholesterol ở một số người.","main":"Cynarin và flavonoid tăng tiết mật, chống oxy hóa và ảnh hưởng chuyển hóa lipid.","contraindications":"Tránh khi tắc mật, sỏi mật có triệu chứng hoặc dị ứng họ Cúc.","side":"Đầy hơi, tiêu chảy, co thắt bụng, dị ứng.","interactions":"Có thể ảnh hưởng thuốc hạ lipid và thuốc chuyển hóa ở gan; dữ liệu tương tác còn hạn chế.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Atis%C3%B4"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Atis%C3%B4%20medicinal%20herb"}]},{"name":"Rau má","aliases":["Centella asiatica","gotu kola"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng hỗ trợ lành vết thương, suy tĩnh mạch và một số triệu chứng lo âu nhẹ.","main":"Triterpenoid thúc đẩy tổng hợp collagen và ảnh hưởng vi tuần hoàn.","contraindications":"Tránh ở bệnh gan, thai kỳ hoặc dùng thuốc an thần/độc gan kéo dài.","side":"Buồn ngủ, đau đầu, kích ứng da; hiếm gặp tổn thương gan.","interactions":"Cộng hợp thuốc an thần; thận trọng với thuốc độc gan.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Rau%20m%C3%A1"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Rau%20m%C3%A1%20medicinal%20herb"}]},{"name":"Nha đam","aliases":["Aloe vera","lô hội"],"category":"Dược liệu/Thuốc Nam","indications":"Gel bôi hỗ trợ bỏng nhẹ và kích ứng da; nhựa mủ aloe uống là thuốc nhuận tràng kích thích nhưng không khuyến cáo dùng kéo dài.","main":"Polysaccharid trong gel giữ ẩm; anthraquinon trong nhựa mủ kích thích đại tràng.","contraindications":"Không uống nhựa mủ khi có thai, tắc ruột, bệnh viêm ruột, suy thận hoặc hạ kali.","side":"Bôi có thể kích ứng; uống nhựa mủ gây đau quặn, tiêu chảy, hạ kali và tổn thương thận.","interactions":"Tăng nguy cơ hạ kali với lợi tiểu/corticosteroid và độc tính digoxin.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Nha%20%C4%91am"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Nha%20%C4%91am%20medicinal%20herb"}]},{"name":"Ngải cứu","aliases":["Artemisia vulgaris","mugwort"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian cho đau bụng kinh, đau cơ khớp và xông cứu; bằng chứng lâm sàng hạn chế.","main":"Tinh dầu và flavonoid có tác dụng chống co thắt/kháng viêm trong nghiên cứu.","contraindications":"Tránh uống khi mang thai, động kinh, dị ứng họ Cúc; không dùng tinh dầu đậm đặc đường uống.","side":"Dị ứng, kích ứng, buồn nôn; tinh dầu liều cao có thể gây co giật.","interactions":"Có thể tương tác thuốc chống co giật và thuốc an thần.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ng%E1%BA%A3i%20c%E1%BB%A9u"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ng%E1%BA%A3i%20c%E1%BB%A9u%20medicinal%20herb"}]},{"name":"Ích mẫu","aliases":["Leonurus japonicus","motherwort"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho kinh nguyệt không đều và sản dịch; không dùng để tự xử trí băng huyết.","main":"Alkaloid leonurine ảnh hưởng cơ trơn tử cung và tuần hoàn.","contraindications":"Chống chỉ định trong thai kỳ; tránh khi rong kinh, chảy máu hoặc dùng thuốc chống đông.","side":"Đau bụng, tiêu chảy, chảy máu tăng; liều cao có thể ảnh hưởng tim mạch.","interactions":"Cộng hợp thuốc chống đông/kháng tiểu cầu và thuốc tác động tim mạch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C3%8Dch%20m%E1%BA%ABu"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C3%8Dch%20m%E1%BA%ABu%20medicinal%20herb"}]},{"name":"Trinh nữ hoàng cung","aliases":["Crinum latifolium"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong một số sản phẩm hỗ trợ triệu chứng u xơ tiền liệt tuyến/u xơ tử cung; không thay thế chẩn đoán ung thư.","main":"Alkaloid crinamin và các chất liên quan được nghiên cứu về tăng sinh tế bào.","contraindications":"Tránh thai kỳ, cho con bú, bệnh gan/thận nặng; không dùng thay điều trị khối u.","side":"Buồn nôn, đau bụng, tiêu chảy; dữ liệu an toàn dài hạn hạn chế.","interactions":"Chưa xác định đầy đủ; thận trọng với thuốc chuyển hóa qua gan.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Trinh%20n%E1%BB%AF%20ho%C3%A0ng%20cung"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Trinh%20n%E1%BB%AF%20ho%C3%A0ng%20cung%20medicinal%20herb"}]},{"name":"Dây thìa canh","aliases":["Gymnema sylvestre","gurmar"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ kiểm soát đường huyết ở người đái tháo đường khi dùng cùng chế độ điều trị chuẩn.","main":"Gymnemic acid giảm cảm nhận vị ngọt và có thể ảnh hưởng hấp thu glucose/tiết insulin.","contraindications":"Tránh tự dùng khi hạ đường huyết, thai kỳ; cần theo dõi đường huyết khi phối hợp thuốc.","side":"Hạ đường huyết, buồn nôn, khó chịu tiêu hóa.","interactions":"Cộng hợp insulin, sulfonylurea, metformin và thuốc hạ đường huyết khác.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=D%C3%A2y%20th%C3%ACa%20canh"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=D%C3%A2y%20th%C3%ACa%20canh%20medicinal%20herb"}]},{"name":"Khổ qua","aliases":["Momordica charantia","mướp đắng","bitter melon"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng như thực phẩm; chế phẩm bổ sung được dùng hỗ trợ đường huyết nhưng hiệu quả không ổn định.","main":"Charantin và polypeptid-p có hoạt tính giống insulin trong nghiên cứu.","contraindications":"Tránh thai kỳ, thiếu G6PD, hạ đường huyết hoặc dùng liều cao ở trẻ em.","side":"Đau bụng, tiêu chảy, hạ đường huyết; hạt có thể độc ở liều cao.","interactions":"Cộng hợp thuốc hạ đường huyết và insulin.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Kh%E1%BB%95%20qua"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Kh%E1%BB%95%20qua%20medicinal%20herb"}]},{"name":"Giảo cổ lam","aliases":["Gynostemma pentaphyllum","jiaogulan"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trà hỗ trợ mỡ máu, đường huyết và sức bền; bằng chứng còn hạn chế.","main":"Gypenosid có hoạt tính chống oxy hóa, chuyển hóa lipid và điều hòa AMPK.","contraindications":"Thận trọng thai kỳ, bệnh tự miễn, chảy máu và trước phẫu thuật.","side":"Buồn nôn, tiêu chảy, chóng mặt; có thể tăng chảy máu.","interactions":"Có thể tương tác thuốc chống đông, hạ đường huyết và ức chế miễn dịch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Gi%E1%BA%A3o%20c%E1%BB%95%20lam"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Gi%E1%BA%A3o%20c%E1%BB%95%20lam%20medicinal%20herb"}]},{"name":"Chè vằng","aliases":["Jasminum subtriplinerve"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian hỗ trợ tiết sữa và tiêu hóa sau sinh; bằng chứng lâm sàng còn ít.","main":"Flavonoid và glycosid có hoạt tính chống oxy hóa/kháng viêm trong nghiên cứu.","contraindications":"Tránh dùng quá đặc ở người huyết áp thấp, thai kỳ hoặc đang suy kiệt.","side":"Khó chịu tiêu hóa, hạ huyết áp, giảm tiết sữa nếu dùng quá đặc theo kinh nghiệm dân gian.","interactions":"Có thể cộng hợp thuốc hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ch%C3%A8%20v%E1%BA%B1ng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ch%C3%A8%20v%E1%BA%B1ng%20medicinal%20herb"}]},{"name":"Lá sen","aliases":["Nelumbo nucifera leaf","hà diệp"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền để thanh thử, hỗ trợ tiêu hóa và kiểm soát cân nặng; bằng chứng giảm cân yếu.","main":"Alkaloid nuciferin và flavonoid ảnh hưởng chuyển hóa lipid trong nghiên cứu.","contraindications":"Thận trọng hạ huyết áp, nhịp chậm, thai kỳ và dùng thuốc giảm cân khác.","side":"Buồn nôn, táo bón hoặc hạ huyết áp.","interactions":"Có thể cộng hợp thuốc hạ áp, hạ đường huyết và an thần.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=L%C3%A1%20sen"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=L%C3%A1%20sen%20medicinal%20herb"}]},{"name":"Tâm sen","aliases":["Nelumbo nucifera plumule","liên tâm"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trà hỗ trợ mất ngủ và bồn chồn; dữ liệu lâm sàng hạn chế.","main":"Alkaloid như neferin có tác động an thần và tim mạch trong nghiên cứu.","contraindications":"Tránh ở nhịp chậm, huyết áp thấp, thai kỳ hoặc dùng thuốc an thần mạnh.","side":"Buồn ngủ, chóng mặt, hạ huyết áp, nhịp chậm.","interactions":"Cộng hợp thuốc an thần, hạ áp và chống loạn nhịp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=T%C3%A2m%20sen"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=T%C3%A2m%20sen%20medicinal%20herb"}]},{"name":"Lạc tiên","aliases":["Passiflora foetida","Passiflora incarnata","passionflower"],"category":"Dược liệu/Thuốc Nam","indications":"Hỗ trợ lo âu nhẹ và mất ngủ ngắn hạn.","main":"Flavonoid có thể điều hòa dẫn truyền GABA.","contraindications":"Tránh khi mang thai, lái xe hoặc dùng cùng rượu/thuốc an thần.","side":"Buồn ngủ, chóng mặt, lú lẫn, rối loạn tiêu hóa.","interactions":"Cộng hợp benzodiazepin, thuốc ngủ, opioid, kháng histamin an thần và rượu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=L%E1%BA%A1c%20ti%C3%AAn"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=L%E1%BA%A1c%20ti%C3%AAn%20medicinal%20herb"}]},{"name":"Bình vôi","aliases":["Stephania rotunda","Stephania glabra"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong chế phẩm an thần, hỗ trợ mất ngủ; hoạt chất rotundin có tác dụng trên thần kinh trung ương.","main":"L-tetrahydropalmatine/rotundin tác động dopamin và hệ thần kinh trung ương.","contraindications":"Tránh thai kỳ, suy gan, lái xe, uống rượu hoặc phối hợp nhiều thuốc an thần.","side":"Buồn ngủ, chóng mặt, hạ huyết áp; quá liều có thể ức chế thần kinh và rối loạn nhịp.","interactions":"Tăng tác dụng thuốc ngủ, benzodiazepin, opioid, kháng histamin an thần và rượu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%C3%ACnh%20v%C3%B4i"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%C3%ACnh%20v%C3%B4i%20medicinal%20herb"}]},{"name":"Vông nem","aliases":["Erythrina variegata","lá vông"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền hỗ trợ mất ngủ và bồn chồn.","main":"Alkaloid erythrin có tác động ức chế thần kinh trung ương.","contraindications":"Tránh thai kỳ, nhược cơ, lái xe và phối hợp thuốc an thần.","side":"Buồn ngủ, yếu cơ, chóng mặt; liều cao có thể độc.","interactions":"Cộng hợp thuốc an thần và giãn cơ.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=V%C3%B4ng%20nem"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=V%C3%B4ng%20nem%20medicinal%20herb"}]},{"name":"Hoa hòe","aliases":["Sophora japonica flower","hòe hoa","rutin"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng hỗ trợ bền thành mạch, trĩ chảy máu và mao mạch dễ vỡ.","main":"Rutin và quercetin có tác động chống oxy hóa và ổn định mao mạch.","contraindications":"Tránh tự điều trị khi chảy máu chưa rõ nguyên nhân; thận trọng với thuốc chống đông.","side":"Rối loạn tiêu hóa, dị ứng; có thể ảnh hưởng đông máu.","interactions":"Có thể tăng nguy cơ chảy máu với thuốc chống đông/kháng tiểu cầu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Hoa%20h%C3%B2e"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Hoa%20h%C3%B2e%20medicinal%20herb"}]},{"name":"Cúc hoa","aliases":["Chrysanthemum morifolium","chrysanthemum"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trà cho đau đầu, mắt mỏi và cảm nóng theo y học cổ truyền.","main":"Flavonoid và tinh dầu có hoạt tính chống oxy hóa/kháng viêm.","contraindications":"Tránh khi dị ứng họ Cúc; thận trọng thai kỳ và huyết áp thấp.","side":"Dị ứng da/hô hấp, khó chịu tiêu hóa.","interactions":"Có thể cộng hợp thuốc hạ áp; dữ liệu tương tác hạn chế.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=C%C3%BAc%20hoa"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=C%C3%BAc%20hoa%20medicinal%20herb"}]},{"name":"Kim ngân hoa","aliases":["Lonicera japonica","honeysuckle"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho viêm họng, mụn nhọt và chứng nhiệt; không thay kháng sinh khi nhiễm khuẩn nặng.","main":"Flavonoid và acid chlorogenic có hoạt tính kháng viêm/kháng khuẩn trong nghiên cứu.","contraindications":"Tránh thai kỳ, tiêu chảy kéo dài, dị ứng; không dùng quả chưa chế biến.","side":"Rối loạn tiêu hóa, dị ứng.","interactions":"Chưa rõ đầy đủ; có thể ảnh hưởng thuốc hạ đường huyết.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Kim%20ng%C3%A2n%20hoa"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Kim%20ng%C3%A2n%20hoa%20medicinal%20herb"}]},{"name":"Xuyên tâm liên","aliases":["Andrographis paniculata","andrographis"],"category":"Dược liệu/Thuốc Nam","indications":"Có thể rút ngắn nhẹ triệu chứng nhiễm khuẩn hô hấp trên không biến chứng ở một số nghiên cứu.","main":"Andrographolide có hoạt tính kháng viêm và điều hòa miễn dịch.","contraindications":"Tránh thai kỳ, vô sinh nam đang điều trị, bệnh tự miễn, thuốc ức chế miễn dịch hoặc dị ứng.","side":"Buồn nôn, tiêu chảy, đau đầu, phát ban; hiếm phản vệ.","interactions":"Có thể tương tác thuốc chống đông, hạ áp, hạ đường huyết và ức chế miễn dịch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Xuy%C3%AAn%20t%C3%A2m%20li%C3%AAn"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Xuy%C3%AAn%20t%C3%A2m%20li%C3%AAn%20medicinal%20herb"}]},{"name":"Bồ công anh","aliases":["Taraxacum officinale","dandelion"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng như thực phẩm và hỗ trợ tiêu hóa/lợi tiểu nhẹ; bằng chứng lâm sàng hạn chế.","main":"Sesquiterpene lacton và inulin có tác động tiêu hóa, lợi tiểu và tiền sinh học.","contraindications":"Tránh khi tắc mật, sỏi mật có triệu chứng, dị ứng họ Cúc hoặc suy thận dùng lợi tiểu.","side":"Ợ nóng, tiêu chảy, dị ứng; có thể tăng tiểu.","interactions":"Tương tác lợi tiểu, lithium, thuốc hạ đường huyết và thuốc chống đông tùy chế phẩm.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BB%93%20c%C3%B4ng%20anh"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BB%93%20c%C3%B4ng%20anh%20medicinal%20herb"}]},{"name":"Mã đề","aliases":["Plantago major","Plantago asiatica"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền lợi tiểu, hỗ trợ ho và kích ứng đường tiết niệu; hạt psyllium là chất xơ nhuận tràng.","main":"Chất nhầy làm dịu niêm mạc; iridoid và flavonoid có hoạt tính kháng viêm.","contraindications":"Tránh khi tắc ruột; uống hạt/chất xơ phải đủ nước. Thận trọng suy thận và thuốc lợi tiểu.","side":"Đầy bụng, dị ứng; nguy cơ tắc nghẽn nếu dùng chất xơ thiếu nước.","interactions":"Chất xơ có thể giảm hấp thu thuốc uống; dùng cách thuốc khác ít nhất vài giờ.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=M%C3%A3%20%C4%91%E1%BB%81"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=M%C3%A3%20%C4%91%E1%BB%81%20medicinal%20herb"}]},{"name":"Râu ngô","aliases":["Zea mays stigma","corn silk"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian lợi tiểu nhẹ và hỗ trợ triệu chứng đường tiểu.","main":"Flavonoid và muối kali có tác động lợi tiểu trong nghiên cứu.","contraindications":"Thận trọng suy thận, rối loạn kali, huyết áp thấp hoặc dùng lợi tiểu.","side":"Tăng tiểu, hạ huyết áp, rối loạn điện giải.","interactions":"Cộng hợp lợi tiểu, thuốc hạ áp và thuốc ảnh hưởng kali.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=R%C3%A2u%20ng%C3%B4"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=R%C3%A2u%20ng%C3%B4%20medicinal%20herb"}]},{"name":"Kim tiền thảo","aliases":["Desmodium styracifolium","Lysimachia christinae"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng hỗ trợ sỏi đường tiết niệu nhỏ và lợi tiểu; không thay xử trí tắc nghẽn/nhiễm khuẩn.","main":"Flavonoid và saponin có thể tăng bài niệu và ảnh hưởng kết tinh sỏi.","contraindications":"Tránh khi tắc đường niệu, đau quặn dữ dội kèm sốt, suy thận nặng hoặc thai kỳ chưa đánh giá.","side":"Đau bụng, tiêu chảy, tăng tiểu, hạ huyết áp.","interactions":"Cộng hợp thuốc lợi tiểu và hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Kim%20ti%E1%BB%81n%20th%E1%BA%A3o"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Kim%20ti%E1%BB%81n%20th%E1%BA%A3o%20medicinal%20herb"}]},{"name":"Cỏ mực","aliases":["Eclipta prostrata","nhọ nồi"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền hỗ trợ cầm máu nhẹ, tóc và chức năng gan; bằng chứng lâm sàng hạn chế.","main":"Wedelolactone và flavonoid có hoạt tính chống oxy hóa và cầm máu trong nghiên cứu.","contraindications":"Không dùng thay cấp cứu xuất huyết; thận trọng thai kỳ và thuốc chống đông.","side":"Rối loạn tiêu hóa, dị ứng; dữ liệu an toàn dài hạn ít.","interactions":"Có thể ảnh hưởng đông máu và thuốc chống đông.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=C%E1%BB%8F%20m%E1%BB%B1c"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=C%E1%BB%8F%20m%E1%BB%B1c%20medicinal%20herb"}]},{"name":"Cỏ tranh","aliases":["Imperata cylindrica","bạch mao căn"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền lợi tiểu và hỗ trợ tiểu máu nhẹ do chứng nhiệt; cần loại trừ nguyên nhân nặng.","main":"Flavonoid và triterpen có tác động lợi tiểu/cầm máu trong nghiên cứu.","contraindications":"Tránh tự điều trị tiểu máu, bí tiểu hoặc suy thận; thận trọng hạ huyết áp.","side":"Tăng tiểu, khó chịu tiêu hóa.","interactions":"Cộng hợp lợi tiểu và thuốc hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=C%E1%BB%8F%20tranh"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=C%E1%BB%8F%20tranh%20medicinal%20herb"}]},{"name":"Cỏ xước","aliases":["Achyranthes aspera","ngưu tất nam"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng Nam dược hỗ trợ đau khớp, lợi tiểu và tuần hoàn.","main":"Saponin và ecdysteroid có hoạt tính kháng viêm trong nghiên cứu.","contraindications":"Tránh thai kỳ, chảy máu, rong kinh hoặc dùng thuốc chống đông.","side":"Đau bụng, tiêu chảy, tăng chảy máu.","interactions":"Có thể cộng hợp chống đông/kháng tiểu cầu và thuốc hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=C%E1%BB%8F%20x%C6%B0%E1%BB%9Bc"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=C%E1%BB%8F%20x%C6%B0%E1%BB%9Bc%20medicinal%20herb"}]},{"name":"Xạ đen","aliases":["Ehretia asperula","Celastrus hindsii"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong sản phẩm hỗ trợ bệnh gan và khối u; chưa đủ bằng chứng để điều trị ung thư.","main":"Polyphenol và triterpen được nghiên cứu về chống oxy hóa và độc tế bào tiền lâm sàng.","contraindications":"Không dùng thay hóa trị/phẫu thuật; thận trọng thai kỳ, bệnh gan/thận và thuốc chống ung thư.","side":"Buồn nôn, tiêu chảy, chóng mặt; dữ liệu độc tính dài hạn hạn chế.","interactions":"Chưa rõ; có thể tương tác thuốc chuyển hóa qua gan và thuốc chống ung thư.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=X%E1%BA%A1%20%C4%91en"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=X%E1%BA%A1%20%C4%91en%20medicinal%20herb"}]},{"name":"An xoa","aliases":["Helicteres hirsuta"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian hỗ trợ chức năng gan; bằng chứng lâm sàng chất lượng cao còn thiếu.","main":"Flavonoid và lignan có hoạt tính chống oxy hóa trong nghiên cứu.","contraindications":"Tránh thai kỳ, trẻ nhỏ, bệnh gan cấp chưa chẩn đoán; không dùng thay thuốc điều trị viêm gan.","side":"Rối loạn tiêu hóa, dị ứng; chưa rõ an toàn dài hạn.","interactions":"Thận trọng với thuốc chuyển hóa qua gan.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=An%20xoa"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=An%20xoa%20medicinal%20herb"}]},{"name":"Nấm linh chi","aliases":["Ganoderma lucidum","reishi","lingzhi"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng hỗ trợ sức khỏe và chất lượng sống; bằng chứng cho ung thư, miễn dịch và tim mạch còn không đồng nhất.","main":"Beta-glucan và triterpen có tác động điều hòa miễn dịch và chống oxy hóa.","contraindications":"Tránh khi chảy máu, trước phẫu thuật, ghép tạng/dùng ức chế miễn dịch hoặc bệnh gan do chế phẩm.","side":"Khô miệng, chóng mặt, rối loạn tiêu hóa, phát ban; hiếm độc gan.","interactions":"Có thể tăng chảy máu, hạ áp/hạ đường huyết và ảnh hưởng thuốc ức chế miễn dịch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=N%E1%BA%A5m%20linh%20chi"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=N%E1%BA%A5m%20linh%20chi%20medicinal%20herb"}]},{"name":"Quế","aliases":["Cinnamomum cassia","Cinnamomum verum","cinnamon","nhục quế"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng gia vị; chế phẩm có thể hỗ trợ nhẹ đường huyết nhưng không thay thuốc đái tháo đường.","main":"Cinnamaldehyde và polyphenol ảnh hưởng nhạy cảm insulin; quế cassia chứa coumarin.","contraindications":"Tránh liều cao kéo dài ở bệnh gan, thai kỳ hoặc dùng chống đông.","side":"Kích ứng miệng, hạ đường huyết; coumarin có thể gây độc gan.","interactions":"Cộng hợp thuốc hạ đường huyết, chống đông và thuốc độc gan.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Qu%E1%BA%BF"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Qu%E1%BA%BF%20medicinal%20herb"}]},{"name":"Bạc hà","aliases":["Mentha arvensis","Mentha piperita","peppermint"],"category":"Dược liệu/Thuốc Nam","indications":"Tinh dầu/menthol dùng giảm nghẹt mũi, đau đầu căng thẳng và khó tiêu; dầu bạc hà bao tan ruột có thể hỗ trợ IBS.","main":"Menthol hoạt hóa thụ thể lạnh; dầu bạc hà làm giãn cơ trơn tiêu hóa.","contraindications":"Tránh bôi tinh dầu đậm đặc gần mũi trẻ nhỏ, trào ngược nặng, tắc mật hoặc dị ứng.","side":"Ợ nóng, kích ứng da/niêm mạc, co thắt thanh quản ở trẻ nếu dùng sai.","interactions":"Có thể ảnh hưởng hấp thu thuốc và enzym gan; dùng cách thuốc kháng acid với viên bao tan ruột.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BA%A1c%20h%C3%A0"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BA%A1c%20h%C3%A0%20medicinal%20herb"}]},{"name":"Tía tô","aliases":["Perilla frutescens","perilla"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng làm thực phẩm và hỗ trợ cảm lạnh, đầy bụng theo y học cổ truyền.","main":"Tinh dầu perillaldehyde và acid rosmarinic có hoạt tính kháng viêm.","contraindications":"Thận trọng dị ứng, thai kỳ và dùng chống đông liều cao.","side":"Dị ứng, kích ứng tiêu hóa.","interactions":"Dữ liệu hạn chế; dầu hạt giàu omega-3 có thể tăng chảy máu khi liều cao.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=T%C3%ADa%20t%C3%B4"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=T%C3%ADa%20t%C3%B4%20medicinal%20herb"}]},{"name":"Húng chanh","aliases":["Plectranthus amboinicus","tần dày lá"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng dân gian hỗ trợ ho và đau họng nhẹ.","main":"Tinh dầu thymol/carvacrol có hoạt tính kháng khuẩn và long đờm trong nghiên cứu.","contraindications":"Không dùng tinh dầu đậm đặc cho trẻ nhỏ; đi khám khi khó thở, sốt cao hoặc ho kéo dài.","side":"Kích ứng tiêu hóa, dị ứng.","interactions":"Chưa xác định tương tác đáng kể ở liều thực phẩm.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=H%C3%BAng%20chanh"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=H%C3%BAng%20chanh%20medicinal%20herb"}]},{"name":"Kinh giới","aliases":["Elsholtzia ciliata","Schizonepeta tenuifolia"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho cảm lạnh, ngứa và dị ứng nhẹ.","main":"Tinh dầu và flavonoid có hoạt tính kháng viêm/kháng histamin tiền lâm sàng.","contraindications":"Thận trọng thai kỳ, chảy máu và dị ứng tinh dầu.","side":"Dị ứng, kích ứng tiêu hóa.","interactions":"Có thể ảnh hưởng thuốc chống đông ở liều dược liệu cao.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Kinh%20gi%E1%BB%9Bi"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Kinh%20gi%E1%BB%9Bi%20medicinal%20herb"}]},{"name":"Sả","aliases":["Cymbopogon citratus","lemongrass"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng làm trà hỗ trợ tiêu hóa và thư giãn; tinh dầu dùng ngoài xua côn trùng.","main":"Citral có hoạt tính kháng khuẩn và giãn cơ nhẹ.","contraindications":"Tránh uống tinh dầu đậm đặc; thận trọng thai kỳ, bệnh gan/thận và hạ huyết áp.","side":"Chóng mặt, khô miệng, kích ứng da, hạ huyết áp.","interactions":"Có thể cộng hợp thuốc an thần và hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=S%E1%BA%A3"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=S%E1%BA%A3%20medicinal%20herb"}]},{"name":"Đinh hương","aliases":["Syzygium aromaticum","clove"],"category":"Dược liệu/Thuốc Nam","indications":"Eugenol dùng tại chỗ giảm đau răng tạm thời; gia vị hỗ trợ tiêu hóa.","main":"Eugenol có tác dụng gây tê, sát khuẩn và ức chế tiểu cầu.","contraindications":"Không nuốt tinh dầu đậm đặc; tránh ở trẻ nhỏ, bệnh gan, chảy máu hoặc trước phẫu thuật.","side":"Kích ứng niêm mạc, tổn thương gan/co giật khi quá liều tinh dầu, tăng chảy máu.","interactions":"Tăng nguy cơ chảy máu với thuốc chống đông/kháng tiểu cầu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90inh%20h%C6%B0%C6%A1ng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90inh%20h%C6%B0%C6%A1ng%20medicinal%20herb"}]},{"name":"Sa nhân","aliases":["Amomum villosum","sa nhân tím"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đầy bụng, buồn nôn và tiêu chảy do hàn thấp.","main":"Tinh dầu cineol/borneol kích thích tiêu hóa và chống co thắt.","contraindications":"Thận trọng thai kỳ và người có trào ngược nặng; tránh tinh dầu liều cao.","side":"Ợ nóng, kích ứng tiêu hóa, dị ứng.","interactions":"Dữ liệu tương tác hạn chế.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Sa%20nh%C3%A2n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Sa%20nh%C3%A2n%20medicinal%20herb"}]},{"name":"Trần bì","aliases":["Citrus reticulata peel","vỏ quýt"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đầy bụng, đờm nhiều và ăn kém.","main":"Tinh dầu limonene và flavonoid ảnh hưởng nhu động tiêu hóa và tiết dịch.","contraindications":"Thận trọng trào ngược, loét dạ dày và tương tác do flavonoid cam quýt.","side":"Ợ nóng, kích ứng dạ dày, dị ứng.","interactions":"Có thể ảnh hưởng enzym chuyển hóa thuốc; mức độ tùy loại vỏ và chế phẩm.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Tr%E1%BA%A7n%20b%C3%AC"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Tr%E1%BA%A7n%20b%C3%AC%20medicinal%20herb"}]},{"name":"Hương phụ","aliases":["Cyperus rotundus","cỏ gấu"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đau bụng kinh, đầy trướng và khí trệ.","main":"Tinh dầu và sesquiterpen có tác dụng chống co thắt tiền lâm sàng.","contraindications":"Tránh thai kỳ hoặc chảy máu bất thường chưa chẩn đoán.","side":"Rối loạn tiêu hóa, dị ứng.","interactions":"Chưa rõ đầy đủ; thận trọng thuốc nội tiết và chống đông.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=H%C6%B0%C6%A1ng%20ph%E1%BB%A5"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=H%C6%B0%C6%A1ng%20ph%E1%BB%A5%20medicinal%20herb"}]},{"name":"Mộc hương","aliases":["Saussurea costus","Aucklandia lappa"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đầy bụng, đau bụng và tiêu hóa kém.","main":"Costunolide và dehydrocostus lactone có tác động chống co thắt/kháng viêm.","contraindications":"Tránh chế phẩm không rõ nguồn do nguy cơ acid aristolochic lẫn tạp; thận trọng thai kỳ.","side":"Dị ứng, kích ứng tiêu hóa; sản phẩm kém chất lượng có thể độc thận.","interactions":"Dữ liệu tương tác hạn chế; ưu tiên sản phẩm kiểm nghiệm.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=M%E1%BB%99c%20h%C6%B0%C6%A1ng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=M%E1%BB%99c%20h%C6%B0%C6%A1ng%20medicinal%20herb"}]},{"name":"Bạch truật","aliases":["Atractylodes macrocephala"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho ăn kém, tiêu chảy mạn và suy nhược kiểu tỳ hư.","main":"Sesquiterpen và polysaccharid có tác động tiêu hóa, miễn dịch tiền lâm sàng.","contraindications":"Thận trọng khô miệng, táo bón, thai kỳ; tránh dùng đơn độc kéo dài nếu chưa đánh giá.","side":"Khô miệng, buồn nôn, dị ứng.","interactions":"Có thể ảnh hưởng đường huyết và thuốc lợi tiểu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BA%A1ch%20tru%E1%BA%ADt"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BA%A1ch%20tru%E1%BA%ADt%20medicinal%20herb"}]},{"name":"Phục linh","aliases":["Wolfiporia cocos","Poria cocos"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền lợi thủy, hỗ trợ phù nhẹ, tiêu hóa và an thần.","main":"Polysaccharid và triterpen có tác động lợi tiểu/điều hòa miễn dịch.","contraindications":"Thận trọng mất nước, suy thận, dùng lợi tiểu hoặc thai kỳ.","side":"Tăng tiểu, khô miệng, rối loạn tiêu hóa.","interactions":"Cộng hợp lợi tiểu và có thể ảnh hưởng thuốc ức chế miễn dịch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ph%E1%BB%A5c%20linh"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ph%E1%BB%A5c%20linh%20medicinal%20herb"}]},{"name":"Hoài sơn","aliases":["Dioscorea opposita","sơn dược"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng như thực phẩm và thuốc bổ tỳ, hỗ trợ tiêu chảy mạn và suy nhược.","main":"Tinh bột, allantoin và diosgenin có tác động dinh dưỡng/niêm mạc.","contraindications":"Thận trọng dị ứng, đái tháo đường khi dùng lượng lớn tinh bột.","side":"Đầy bụng, táo bón, dị ứng hiếm.","interactions":"Có thể ảnh hưởng đường huyết.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ho%C3%A0i%20s%C6%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ho%C3%A0i%20s%C6%A1n%20medicinal%20herb"}]},{"name":"Thục địa","aliases":["Rehmannia glutinosa prepared root"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong bài thuốc bổ huyết, bổ âm; thường không dùng đơn độc cho triệu chứng cấp.","main":"Iridoid glycosid và đường có tác động huyết học/chuyển hóa tiền lâm sàng.","contraindications":"Thận trọng tiêu chảy, đầy bụng, đái tháo đường, thai kỳ.","side":"Đầy bụng, tiêu chảy, buồn nôn.","interactions":"Có thể cộng hợp thuốc hạ đường huyết và chống đông; dữ liệu hạn chế.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Th%E1%BB%A5c%20%C4%91%E1%BB%8Ba"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Th%E1%BB%A5c%20%C4%91%E1%BB%8Ba%20medicinal%20herb"}]},{"name":"Đan sâm","aliases":["Salvia miltiorrhiza","danshen"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đau ngực và ứ huyết; không thay điều trị hội chứng vành cấp.","main":"Tanshinone và salvianolic acid ảnh hưởng tiểu cầu, mạch máu và vi tuần hoàn.","contraindications":"Tránh khi chảy máu, thai kỳ, trước phẫu thuật hoặc dùng chống đông/kháng tiểu cầu.","side":"Chảy máu, chóng mặt, rối loạn tiêu hóa, dị ứng.","interactions":"Tăng mạnh nguy cơ chảy máu và có thể làm tăng INR với warfarin/acenocoumarol.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90an%20s%C3%A2m"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90an%20s%C3%A2m%20medicinal%20herb"}]},{"name":"Xuyên khung","aliases":["Ligusticum striatum","Ligusticum chuanxiong"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đau đầu và đau do huyết ứ.","main":"Ligustilide và acid ferulic ảnh hưởng mạch máu và tiểu cầu.","contraindications":"Tránh thai kỳ, rong kinh, chảy máu hoặc dùng chống đông.","side":"Đau đầu, chóng mặt, tăng chảy máu, rối loạn tiêu hóa.","interactions":"Cộng hợp thuốc chống đông/kháng tiểu cầu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Xuy%C3%AAn%20khung"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Xuy%C3%AAn%20khung%20medicinal%20herb"}]},{"name":"Bạch thược","aliases":["Paeonia lactiflora","white peony"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong bài thuốc cho co thắt, đau bụng kinh và chứng huyết hư.","main":"Paeoniflorin có tác động chống co thắt, kháng viêm và miễn dịch.","contraindications":"Thận trọng chảy máu, tiêu chảy, thai kỳ và thuốc chống đông.","side":"Đau bụng, tiêu chảy, dị ứng.","interactions":"Có thể tăng chảy máu và ảnh hưởng thuốc ức chế miễn dịch.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BA%A1ch%20th%C6%B0%E1%BB%A3c"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BA%A1ch%20th%C6%B0%E1%BB%A3c%20medicinal%20herb"}]},{"name":"Ngưu tất","aliases":["Achyranthes bidentata"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đau lưng gối và hoạt huyết, lợi niệu.","main":"Saponin và ecdysterone có tác động xương/viêm tiền lâm sàng.","contraindications":"Chống chỉ định thai kỳ; tránh rong kinh, chảy máu hoặc huyết áp thấp.","side":"Đau bụng, tiêu chảy, tăng chảy máu.","interactions":"Cộng hợp chống đông/kháng tiểu cầu và hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ng%C6%B0u%20t%E1%BA%A5t"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ng%C6%B0u%20t%E1%BA%A5t%20medicinal%20herb"}]},{"name":"Đỗ trọng","aliases":["Eucommia ulmoides"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền hỗ trợ đau lưng, gân xương và huyết áp.","main":"Lignan và iridoid có tác động lên xương và mạch máu tiền lâm sàng.","contraindications":"Thận trọng huyết áp thấp, thai kỳ và phối hợp nhiều thuốc hạ áp.","side":"Chóng mặt, hạ huyết áp, rối loạn tiêu hóa.","interactions":"Cộng hợp thuốc hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90%E1%BB%97%20tr%E1%BB%8Dng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90%E1%BB%97%20tr%E1%BB%8Dng%20medicinal%20herb"}]},{"name":"Tang ký sinh","aliases":["Taxillus chinensis","Loranthus parasiticus"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong bài thuốc đau lưng, phong thấp và dưỡng thai theo YHCT; cần định danh đúng dược liệu.","main":"Flavonoid và polyphenol có hoạt tính kháng viêm tiền lâm sàng.","contraindications":"Không tự dùng trong thai kỳ; tránh dược liệu không rõ nguồn hoặc ký sinh trên cây độc.","side":"Rối loạn tiêu hóa, dị ứng; độc tính phụ thuộc nguồn cây chủ.","interactions":"Dữ liệu tương tác hạn chế; thận trọng thuốc hạ áp và chống đông.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Tang%20k%C3%BD%20sinh"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Tang%20k%C3%BD%20sinh%20medicinal%20herb"}]},{"name":"Ý dĩ","aliases":["Coix lacryma-jobi","bo bo","coix seed"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng như thực phẩm; y học cổ truyền dùng lợi thấp, hỗ trợ tiêu chảy và đau khớp.","main":"Tinh bột, lipid và coixenol có tác động dinh dưỡng/kháng viêm tiền lâm sàng.","contraindications":"Tránh dùng liều dược liệu trong thai kỳ; thận trọng người hạ đường huyết.","side":"Đầy bụng, táo bón hoặc dị ứng.","interactions":"Có thể cộng hợp thuốc hạ đường huyết.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C3%9D%20d%C4%A9"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C3%9D%20d%C4%A9%20medicinal%20herb"}]},{"name":"Liên nhục","aliases":["Nelumbo nucifera seed","hạt sen"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng làm thực phẩm và hỗ trợ tiêu chảy mạn, suy nhược, mất ngủ nhẹ.","main":"Tinh bột, protein và alkaloid có tác động dinh dưỡng/an thần nhẹ.","contraindications":"Thận trọng táo bón, đầy bụng và đái tháo đường khi dùng nhiều.","side":"Táo bón, đầy bụng.","interactions":"Ít tương tác ở liều thực phẩm; có thể cộng hợp thuốc an thần nếu dùng cùng tâm sen.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Li%C3%AAn%20nh%E1%BB%A5c"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Li%C3%AAn%20nh%E1%BB%A5c%20medicinal%20herb"}]},{"name":"Mạch môn","aliases":["Ophiopogon japonicus"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền làm dịu ho khan, khô miệng và dưỡng âm.","main":"Saponin steroid và polysaccharid có tác động chống viêm/niêm mạc.","contraindications":"Thận trọng tiêu chảy, đầy bụng, thai kỳ và dị ứng.","side":"Đau bụng, tiêu chảy, buồn nôn.","interactions":"Có thể ảnh hưởng đường huyết và nhịp tim; dữ liệu hạn chế.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=M%E1%BA%A1ch%20m%C3%B4n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=M%E1%BA%A1ch%20m%C3%B4n%20medicinal%20herb"}]},{"name":"Ngũ vị tử","aliases":["Schisandra chinensis","schisandra"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng hỗ trợ mệt mỏi và chức năng gan; có khả năng tương tác thuốc đáng kể.","main":"Schisandrin ảnh hưởng enzym CYP và P-glycoprotein, đồng thời có hoạt tính chống oxy hóa.","contraindications":"Tránh thai kỳ, động kinh, trào ngược nặng và dùng thuốc có khoảng điều trị hẹp nếu chưa đánh giá.","side":"Ợ nóng, đau bụng, mất ngủ, dị ứng.","interactions":"Có thể tăng/giảm nồng độ tacrolimus, cyclosporin, warfarin và nhiều thuốc chuyển hóa qua CYP/P-gp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ng%C5%A9%20v%E1%BB%8B%20t%E1%BB%AD"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ng%C5%A9%20v%E1%BB%8B%20t%E1%BB%AD%20medicinal%20herb"}]},{"name":"Hoàng liên","aliases":["Coptis chinensis","berberine herb"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho tiêu chảy nhiễm khuẩn và chứng thấp nhiệt; không dùng kéo dài tùy tiện.","main":"Berberin và alkaloid isoquinolin có hoạt tính kháng khuẩn và chuyển hóa.","contraindications":"Tránh thai kỳ, trẻ sơ sinh, vàng da, bệnh gan nặng; thận trọng hạ đường huyết/huyết áp.","side":"Táo bón, đau bụng, buồn nôn; liều cao có thể ảnh hưởng tim mạch.","interactions":"Berberin ức chế CYP/P-gp; tương tác cyclosporin/tacrolimus, thuốc hạ đường huyết, chống loạn nhịp và chống đông.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ho%C3%A0ng%20li%C3%AAn"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ho%C3%A0ng%20li%C3%AAn%20medicinal%20herb"}]},{"name":"Hoàng cầm","aliases":["Scutellaria baicalensis","baical skullcap"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho viêm và chứng nhiệt; bằng chứng hiện đại còn hạn chế.","main":"Baicalin/baicalein có hoạt tính chống viêm và chống oxy hóa.","contraindications":"Tránh bệnh gan, thai kỳ và sản phẩm phối hợp không rõ nguồn.","side":"Rối loạn tiêu hóa, buồn ngủ; hiếm tổn thương gan.","interactions":"Có thể tương tác thuốc an thần, chống đông và thuốc chuyển hóa qua gan.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ho%C3%A0ng%20c%E1%BA%A7m"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ho%C3%A0ng%20c%E1%BA%A7m%20medicinal%20herb"}]},{"name":"Chi tử","aliases":["Gardenia jasminoides","quả dành dành"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho sốt, bứt rứt và vàng da; không thay xử trí tắc mật.","main":"Geniposide có tác động kháng viêm và lợi mật tiền lâm sàng.","contraindications":"Tránh tiêu chảy, thai kỳ và dùng kéo dài; thận trọng bệnh gan/mật.","side":"Tiêu chảy, đau bụng; dùng kéo dài liều cao có báo cáo tổn thương đại tràng.","interactions":"Có thể ảnh hưởng thuốc hạ đường huyết và thuốc gan mật.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Chi%20t%E1%BB%AD"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Chi%20t%E1%BB%AD%20medicinal%20herb"}]},{"name":"Đại hoàng","aliases":["Rheum palmatum","rhubarb root"],"category":"Dược liệu/Thuốc Nam","indications":"Nhuận tràng kích thích ngắn hạn; dùng cổ truyền trong một số bài tả hạ.","main":"Sennosid/anthraquinon kích thích nhu động và bài tiết đại tràng.","contraindications":"Tránh thai kỳ, cho con bú, trẻ nhỏ, tắc ruột, đau bụng chưa rõ nguyên nhân, bệnh viêm ruột hoặc mất nước.","side":"Đau quặn, tiêu chảy, hạ kali; lệ thuộc nhuận tràng khi lạm dụng.","interactions":"Hạ kali làm tăng độc tính digoxin; tương tác lợi tiểu, corticosteroid và thuốc chống loạn nhịp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90%E1%BA%A1i%20ho%C3%A0ng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90%E1%BA%A1i%20ho%C3%A0ng%20medicinal%20herb"}]},{"name":"Phan tả diệp","aliases":["Senna alexandrina","senna"],"category":"Dược liệu/Thuốc Nam","indications":"Điều trị táo bón ngắn hạn hoặc làm sạch ruột theo chỉ định.","main":"Sennosid kích thích thần kinh đại tràng và tăng bài tiết nước.","contraindications":"Tránh tắc ruột, đau bụng chưa chẩn đoán, mất nước, bệnh viêm ruột cấp; không dùng kéo dài.","side":"Đau quặn, tiêu chảy, hạ kali, đổi màu nước tiểu; lạm dụng gây lệ thuộc.","interactions":"Tương tác digoxin, lợi tiểu, corticosteroid và thuốc chống loạn nhịp do hạ kali.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Phan%20t%E1%BA%A3%20di%E1%BB%87p"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Phan%20t%E1%BA%A3%20di%E1%BB%87p%20medicinal%20herb"}]},{"name":"Bán hạ chế","aliases":["Pinellia ternata processed","bán hạ"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong bài thuốc giảm đờm, buồn nôn; chỉ dùng loại đã chế biến đúng.","main":"Chất kích ứng calcium oxalate giảm sau chế biến; alkaloid và polysaccharid có tác động chống nôn/long đờm.","contraindications":"Tuyệt đối không dùng bán hạ sống; tránh thai kỳ và tổn thương niêm mạc.","side":"Bán hạ sống gây bỏng rát, phù họng, nôn; chế phẩm vẫn có thể kích ứng.","interactions":"Dữ liệu tương tác hạn chế; dùng trong bài thuốc dưới giám sát chuyên môn.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%C3%A1n%20h%E1%BA%A1%20ch%E1%BA%BF"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%C3%A1n%20h%E1%BA%A1%20ch%E1%BA%BF%20medicinal%20herb"}]},{"name":"Thiên ma","aliases":["Gastrodia elata"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho chóng mặt, đau đầu và co giật; không thay thuốc chống động kinh.","main":"Gastrodin tác động thần kinh, GABA và tuần hoàn não trong nghiên cứu.","contraindications":"Thận trọng thai kỳ, huyết áp thấp, dùng thuốc an thần/chống co giật.","side":"Chóng mặt, buồn ngủ, khô miệng, dị ứng.","interactions":"Cộng hợp thuốc an thần, chống co giật và hạ áp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Thi%C3%AAn%20ma"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Thi%C3%AAn%20ma%20medicinal%20herb"}]},{"name":"Câu đằng","aliases":["Uncaria rhynchophylla","gou teng"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền cho đau đầu, chóng mặt và tăng huyết áp kiểu can dương.","main":"Alkaloid rhynchophylline ảnh hưởng kênh calci và mạch máu.","contraindications":"Thận trọng huyết áp thấp, nhịp chậm, thai kỳ và thuốc hạ áp.","side":"Chóng mặt, hạ huyết áp, buồn nôn.","interactions":"Cộng hợp thuốc hạ áp và chống loạn nhịp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=C%C3%A2u%20%C4%91%E1%BA%B1ng"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=C%C3%A2u%20%C4%91%E1%BA%B1ng%20medicinal%20herb"}]},{"name":"Viễn chí","aliases":["Polygala tenuifolia"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng cổ truyền hỗ trợ trí nhớ, lo âu và đờm; bằng chứng hạn chế.","main":"Saponin và oligosaccharid có tác động thần kinh tiền lâm sàng.","contraindications":"Tránh loét dạ dày, thai kỳ và dùng liều cao.","side":"Buồn nôn, kích ứng dạ dày, chóng mặt.","interactions":"Có thể cộng hợp thuốc an thần và kích ứng tiêu hóa với NSAID.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vi%E1%BB%85n%20ch%C3%AD"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Vi%E1%BB%85n%20ch%C3%AD%20medicinal%20herb"}]},{"name":"Toan táo nhân","aliases":["Ziziphus jujuba spinosa seed","suan zao ren"],"category":"Dược liệu/Thuốc Nam","indications":"Dùng trong bài thuốc mất ngủ, hồi hộp và lo âu.","main":"Jujubosid có tác động lên GABA và serotonin trong nghiên cứu.","contraindications":"Tránh lái xe, thai kỳ và phối hợp nhiều thuốc an thần.","side":"Buồn ngủ, chóng mặt, rối loạn tiêu hóa.","interactions":"Cộng hợp benzodiazepin, thuốc ngủ, opioid, kháng histamin an thần và rượu.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Toan%20t%C3%A1o%20nh%C3%A2n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Toan%20t%C3%A1o%20nh%C3%A2n%20medicinal%20herb"}]},{"name":"Lục vị địa hoàng hoàn","aliases":["lục vị","liu wei di huang wan"],"category":"Bài thuốc cổ truyền","indications":"Bài thuốc bổ thận âm dùng cho lưng gối mỏi, chóng mặt, ù tai, khô miệng theo biện chứng YHCT.","main":"Phối hợp thục địa, sơn thù, hoài sơn, trạch tả, phục linh, mẫu đơn bì; tác dụng phụ thuộc thể bệnh, không đồng nghĩa điều trị suy thận hiện đại.","contraindications":"Không dùng tùy tiện khi tiêu chảy, đầy bụng, đàm thấp, nhiễm trùng cấp hoặc chưa phân biệt âm hư/dương hư.","side":"Đầy bụng, tiêu chảy, buồn nôn; dị ứng dược liệu.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=L%E1%BB%A5c%20v%E1%BB%8B%20%C4%91%E1%BB%8Ba%20ho%C3%A0ng%20ho%C3%A0n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=L%E1%BB%A5c%20v%E1%BB%8B%20%C4%91%E1%BB%8Ba%20ho%C3%A0ng%20ho%C3%A0n%20medicinal%20herb"}]},{"name":"Bát vị quế phụ hoàn","aliases":["bát vị","kim quỹ thận khí hoàn","jin gui shen qi wan"],"category":"Bài thuốc cổ truyền","indications":"Bài ôn bổ thận dương cho lạnh, lưng gối mỏi, tiểu nhiều/phù nhẹ theo biện chứng YHCT.","main":"Lục vị gia quế và phụ tử chế; có tác dụng ôn dương và lợi thủy.","contraindications":"Chống chỉ định tự dùng phụ tử không chuẩn hóa; tránh thai kỳ, sốt/nhiệt thịnh, rối loạn nhịp và tăng huyết áp chưa kiểm soát.","side":"Buồn nôn, tê môi, hồi hộp, loạn nhịp nếu phụ tử không chế biến đúng; rối loạn tiêu hóa.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%C3%A1t%20v%E1%BB%8B%20qu%E1%BA%BF%20ph%E1%BB%A5%20ho%C3%A0n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%C3%A1t%20v%E1%BB%8B%20qu%E1%BA%BF%20ph%E1%BB%A5%20ho%C3%A0n%20medicinal%20herb"}]},{"name":"Bổ trung ích khí thang","aliases":["bu zhong yi qi tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho mệt mỏi, ăn kém, sa tạng và tiêu chảy mạn theo thể khí hư hạ hãm.","main":"Hoàng kỳ, nhân sâm/đảng sâm, bạch truật, cam thảo, đương quy, trần bì, thăng ma, sài hồ.","contraindications":"Thận trọng tăng huyết áp, mất ngủ, bệnh tự miễn, nhiễm trùng cấp và dùng cam thảo kéo dài.","side":"Mất ngủ, tăng huyết áp, phù/hạ kali do cam thảo, đầy bụng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BB%95%20trung%20%C3%ADch%20kh%C3%AD%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BB%95%20trung%20%C3%ADch%20kh%C3%AD%20thang%20medicinal%20herb"}]},{"name":"Quy tỳ thang","aliases":["gui pi tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho mất ngủ, hồi hộp, hay quên, ăn kém và xuất huyết nhẹ theo thể tâm tỳ hư.","main":"Phối hợp thuốc bổ khí, dưỡng huyết và an thần như nhân sâm, hoàng kỳ, đương quy, long nhãn, toan táo nhân.","contraindications":"Không tự dùng khi chảy máu chưa rõ nguyên nhân, tăng huyết áp hoặc dùng nhiều thuốc an thần/chống đông.","side":"Buồn ngủ, đầy bụng, dị ứng; có thể ảnh hưởng huyết áp và đông máu.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Quy%20t%E1%BB%B3%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Quy%20t%E1%BB%B3%20thang%20medicinal%20herb"}]},{"name":"Tiêu dao tán","aliases":["xiao yao san","gia vị tiêu dao"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho căng thẳng, đau tức ngực sườn, kinh nguyệt không đều theo thể can uất tỳ hư.","main":"Sài hồ, đương quy, bạch thược, bạch truật, phục linh, cam thảo, bạc hà và gừng.","contraindications":"Tránh tự điều trị đau ngực, trầm cảm nặng hoặc xuất huyết; thận trọng thai kỳ và bệnh gan.","side":"Rối loạn tiêu hóa, đau đầu, dị ứng; cam thảo có thể gây phù/hạ kali.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ti%C3%AAu%20dao%20t%C3%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ti%C3%AAu%20dao%20t%C3%A1n%20medicinal%20herb"}]},{"name":"Tứ vật thang","aliases":["si wu tang"],"category":"Bài thuốc cổ truyền","indications":"Bài bổ huyết dùng cho da xanh, chóng mặt, kinh ít theo thể huyết hư.","main":"Thục địa, đương quy, bạch thược, xuyên khung; có tác động lên huyết học và tuần hoàn.","contraindications":"Tránh khi đang chảy máu nhiều, rong kinh, thai kỳ chưa đánh giá hoặc dùng chống đông.","side":"Đầy bụng, tiêu chảy, tăng chảy máu hoặc dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=T%E1%BB%A9%20v%E1%BA%ADt%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=T%E1%BB%A9%20v%E1%BA%ADt%20thang%20medicinal%20herb"}]},{"name":"Tứ quân tử thang","aliases":["si jun zi tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho mệt mỏi, ăn kém, phân lỏng theo thể tỳ khí hư.","main":"Nhân sâm/đảng sâm, bạch truật, phục linh, cam thảo.","contraindications":"Thận trọng tăng huyết áp, phù/hạ kali, bệnh tự miễn và nhiễm trùng cấp.","side":"Đầy bụng, mất ngủ, tăng huyết áp hoặc phù do cam thảo.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=T%E1%BB%A9%20qu%C3%A2n%20t%E1%BB%AD%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=T%E1%BB%A9%20qu%C3%A2n%20t%E1%BB%AD%20thang%20medicinal%20herb"}]},{"name":"Thập toàn đại bổ","aliases":["shi quan da bu tang"],"category":"Bài thuốc cổ truyền","indications":"Bổ khí huyết cho suy nhược sau bệnh theo biện chứng YHCT.","main":"Tứ quân tử + tứ vật, thêm hoàng kỳ và quế; tác động rộng nên tương tác nhiều.","contraindications":"Tránh sốt/nhiễm trùng cấp, tăng huyết áp chưa kiểm soát, chảy máu hoặc ung thư đang điều trị nếu chưa trao đổi bác sĩ.","side":"Đầy bụng, mất ngủ, tăng huyết áp, dị ứng, tăng chảy máu.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Th%E1%BA%ADp%20to%C3%A0n%20%C4%91%E1%BA%A1i%20b%E1%BB%95"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Th%E1%BA%ADp%20to%C3%A0n%20%C4%91%E1%BA%A1i%20b%E1%BB%95%20medicinal%20herb"}]},{"name":"Độc hoạt tang ký sinh thang","aliases":["du huo ji sheng tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho đau lưng khớp mạn kèm lạnh, yếu gân xương theo YHCT.","main":"Phối hợp khu phong thấp, bổ can thận và dưỡng huyết.","contraindications":"Không dùng thay đánh giá đau lưng có dấu hiệu thần kinh; tránh thai kỳ và thuốc chống đông nếu chưa kiểm tra.","side":"Rối loạn tiêu hóa, chóng mặt, tăng chảy máu hoặc dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=%C4%90%E1%BB%99c%20ho%E1%BA%A1t%20tang%20k%C3%BD%20sinh%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=%C4%90%E1%BB%99c%20ho%E1%BA%A1t%20tang%20k%C3%BD%20sinh%20thang%20medicinal%20herb"}]},{"name":"Hoắc hương chính khí","aliases":["huo xiang zheng qi"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho đầy bụng, nôn, tiêu chảy và cảm mạo kèm thấp trệ theo YHCT.","main":"Hoắc hương cùng bán hạ chế, hậu phác, trần bì, phục linh và các vị hành khí hóa thấp.","contraindications":"Không dùng khi mất nước nặng, sốt cao, phân máu hoặc nghi nhiễm khuẩn nặng; tránh bán hạ sống.","side":"Buồn nôn, kích ứng tiêu hóa, dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ho%E1%BA%AFc%20h%C6%B0%C6%A1ng%20ch%C3%ADnh%20kh%C3%AD"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ho%E1%BA%AFc%20h%C6%B0%C6%A1ng%20ch%C3%ADnh%20kh%C3%AD%20medicinal%20herb"}]},{"name":"Nhị trần thang","aliases":["er chen tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho ho đờm nhiều, buồn nôn và chóng mặt do đàm thấp theo YHCT.","main":"Bán hạ chế, trần bì, phục linh, cam thảo; hóa đàm và điều hòa tiêu hóa.","contraindications":"Không dùng bán hạ sống; thận trọng ho khan, thai kỳ, hạ kali và tăng huyết áp.","side":"Kích ứng họng/dạ dày, phù hoặc hạ kali do cam thảo.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Nh%E1%BB%8B%20tr%E1%BA%A7n%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Nh%E1%BB%8B%20tr%E1%BA%A7n%20thang%20medicinal%20herb"}]},{"name":"Sâm linh bạch truật tán","aliases":["shen ling bai zhu san"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho tiêu chảy mạn, ăn kém và suy nhược theo thể tỳ khí hư thấp.","main":"Nhân sâm/đảng sâm, bạch truật, phục linh, hoài sơn, ý dĩ, liên nhục và các vị kiện tỳ.","contraindications":"Không tự dùng khi tiêu chảy cấp có sốt/máu, mất nước hoặc tắc ruột.","side":"Đầy bụng, táo bón, mất ngủ hoặc dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=S%C3%A2m%20linh%20b%E1%BA%A1ch%20tru%E1%BA%ADt%20t%C3%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=S%C3%A2m%20linh%20b%E1%BA%A1ch%20tru%E1%BA%ADt%20t%C3%A1n%20medicinal%20herb"}]},{"name":"Bảo hòa hoàn","aliases":["bao he wan"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho đầy bụng, ợ chua, ăn không tiêu do thực tích theo YHCT.","main":"Sơn tra, thần khúc, bán hạ chế, phục linh, trần bì, liên kiều và lai phục tử.","contraindications":"Tránh đau bụng cấp chưa rõ nguyên nhân, loét tiến triển, thai kỳ và trẻ nhỏ nếu chưa đánh giá.","side":"Ợ nóng, tiêu chảy, kích ứng tiêu hóa.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BA%A3o%20h%C3%B2a%20ho%C3%A0n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BA%A3o%20h%C3%B2a%20ho%C3%A0n%20medicinal%20herb"}]},{"name":"Ngân kiều tán","aliases":["yin qiao san"],"category":"Bài thuốc cổ truyền","indications":"Dùng giai đoạn sớm cảm sốt, đau họng theo thể phong nhiệt; không thay kháng sinh khi có nhiễm khuẩn nặng.","main":"Kim ngân hoa, liên kiều, bạc hà, cát cánh và các vị thanh nhiệt giải biểu.","contraindications":"Không tự dùng khi khó thở, sốt cao kéo dài, dị ứng dược liệu hoặc thai kỳ.","side":"Dị ứng, tiêu chảy, kích ứng tiêu hóa.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ng%C3%A2n%20ki%E1%BB%81u%20t%C3%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ng%C3%A2n%20ki%E1%BB%81u%20t%C3%A1n%20medicinal%20herb"}]},{"name":"Ma hoàng thang","aliases":["ma huang tang"],"category":"Bài thuốc cổ truyền","indications":"Bài phát hãn cho cảm phong hàn không mồ hôi theo YHCT; chứa ma hoàng có tác dụng giao cảm mạnh.","main":"Ephedrin từ ma hoàng kích thích alpha/beta adrenergic, giãn phế quản và tăng nhịp tim.","contraindications":"Tránh tăng huyết áp, bệnh mạch vành, loạn nhịp, cường giáp, glaucoma, thai kỳ, dùng MAOI hoặc chất kích thích.","side":"Hồi hộp, tăng huyết áp, mất ngủ, run, bí tiểu, loạn nhịp; có thể nguy hiểm.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ma%20ho%C3%A0ng%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ma%20ho%C3%A0ng%20thang%20medicinal%20herb"}]},{"name":"Quế chi thang","aliases":["gui zhi tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho cảm phong hàn có mồ hôi, sợ gió theo YHCT.","main":"Quế chi, bạch thược, gừng, đại táo và cam thảo điều hòa dinh vệ.","contraindications":"Thận trọng sốt cao, chảy máu, bệnh gan và dùng chống đông.","side":"Ợ nóng, dị ứng, tăng chảy máu hoặc phù/hạ kali do cam thảo.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Qu%E1%BA%BF%20chi%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Qu%E1%BA%BF%20chi%20thang%20medicinal%20herb"}]},{"name":"Tiểu sài hồ thang","aliases":["xiao chai hu tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho chứng bán biểu bán lý như sốt rét qua lại, đầy tức hạ sườn theo YHCT.","main":"Sài hồ, hoàng cầm, bán hạ chế, nhân sâm, cam thảo, gừng, đại táo.","contraindications":"Tránh tự dùng kéo dài; đã có báo cáo viêm phổi kẽ và tổn thương gan, đặc biệt khi phối hợp interferon.","side":"Buồn nôn, phát ban, tăng men gan; hiếm viêm phổi kẽ.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ti%E1%BB%83u%20s%C3%A0i%20h%E1%BB%93%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ti%E1%BB%83u%20s%C3%A0i%20h%E1%BB%93%20thang%20medicinal%20herb"}]},{"name":"Ngũ linh tán","aliases":["wu ling san"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho rối loạn phân bố dịch, phù nhẹ, tiểu ít theo YHCT.","main":"Trạch tả, phục linh, trư linh, bạch truật, quế chi; tác động lợi thủy.","contraindications":"Tránh mất nước, suy thận cấp, rối loạn điện giải hoặc dùng lợi tiểu mạnh nếu chưa đánh giá.","side":"Tăng tiểu, chóng mặt, mất nước, rối loạn điện giải.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ng%C5%A9%20linh%20t%C3%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ng%C5%A9%20linh%20t%C3%A1n%20medicinal%20herb"}]},{"name":"Chân vũ thang","aliases":["zhen wu tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho phù, chóng mặt, lạnh và tiêu chảy theo thể dương hư thủy tràn.","main":"Phụ tử chế, phục linh, bạch truật, bạch thược, gừng.","contraindications":"Không tự dùng phụ tử; tránh loạn nhịp, thai kỳ, tăng huyết áp và dược liệu không chuẩn hóa.","side":"Tê môi, nôn, hồi hộp, loạn nhịp do phụ tử; mất nước.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ch%C3%A2n%20v%C5%A9%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ch%C3%A2n%20v%C5%A9%20thang%20medicinal%20herb"}]},{"name":"Thiên ma câu đằng ẩm","aliases":["tian ma gou teng yin"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho đau đầu, chóng mặt, tăng huyết áp theo thể can dương thượng cang.","main":"Thiên ma, câu đằng và các vị bình can, hoạt huyết, bổ can thận.","contraindications":"Không thay điều trị cấp cứu tăng huyết áp; thận trọng huyết áp thấp, nhịp chậm và chống đông.","side":"Chóng mặt, hạ huyết áp, buồn ngủ, tăng chảy máu.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Thi%C3%AAn%20ma%20c%C3%A2u%20%C4%91%E1%BA%B1ng%20%E1%BA%A9m"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Thi%C3%AAn%20ma%20c%C3%A2u%20%C4%91%E1%BA%B1ng%20%E1%BA%A9m%20medicinal%20herb"}]},{"name":"Huyết phủ trục ứ thang","aliases":["xue fu zhu yu tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho đau cố định, đau ngực/đầu do huyết ứ theo YHCT; phải loại trừ bệnh tim mạch cấp.","main":"Đào nhân, hồng hoa, đương quy, xuyên khung, xích thược và các vị hoạt huyết.","contraindications":"Tránh thai kỳ, chảy máu, trước phẫu thuật hoặc dùng thuốc chống đông/kháng tiểu cầu.","side":"Tăng chảy máu, đau bụng, tiêu chảy, dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Huy%E1%BA%BFt%20ph%E1%BB%A7%20tr%E1%BB%A5c%20%E1%BB%A9%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Huy%E1%BA%BFt%20ph%E1%BB%A7%20tr%E1%BB%A5c%20%E1%BB%A9%20thang%20medicinal%20herb"}]},{"name":"Bổ dương hoàn ngũ thang","aliases":["bu yang huan wu tang"],"category":"Bài thuốc cổ truyền","indications":"Dùng phục hồi di chứng yếu liệt theo YHCT; không dùng trong giai đoạn cấp đột quỵ nếu chưa đánh giá.","main":"Hoàng kỳ liều cao phối hợp đương quy, xuyên khung, đào nhân, hồng hoa, địa long để ích khí hoạt huyết.","contraindications":"Tránh giai đoạn xuất huyết cấp, chảy máu, thai kỳ và dùng chống đông nếu chưa theo dõi.","side":"Tăng chảy máu, thay đổi huyết áp, rối loạn tiêu hóa.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BB%95%20d%C6%B0%C6%A1ng%20ho%C3%A0n%20ng%C5%A9%20thang"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BB%95%20d%C6%B0%C6%A1ng%20ho%C3%A0n%20ng%C5%A9%20thang%20medicinal%20herb"}]},{"name":"Sinh mạch tán","aliases":["sheng mai san"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho mệt, hụt hơi, khát và ra mồ hôi theo thể khí âm lưỡng hư.","main":"Nhân sâm, mạch môn, ngũ vị tử; ảnh hưởng tim mạch, thần kinh và chuyển hóa thuốc.","contraindications":"Thận trọng loạn nhịp, mất ngủ, bệnh tự miễn và thuốc có khoảng điều trị hẹp.","side":"Mất ngủ, đau bụng, hồi hộp, dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Sinh%20m%E1%BA%A1ch%20t%C3%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Sinh%20m%E1%BA%A1ch%20t%C3%A1n%20medicinal%20herb"}]},{"name":"Thương nhĩ tử tán","aliases":["cang er zi san"],"category":"Bài thuốc cổ truyền","indications":"Dùng cho nghẹt mũi, viêm xoang theo YHCT.","main":"Thương nhĩ tử, tân di, bạch chỉ, bạc hà; thông khiếu và giảm viêm.","contraindications":"Thương nhĩ tử có độc tính nếu quá liều; tránh thai kỳ, bệnh gan/thận và tự dùng kéo dài.","side":"Buồn nôn, đau bụng, chóng mặt; quá liều có thể độc gan/thận.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Th%C6%B0%C6%A1ng%20nh%C4%A9%20t%E1%BB%AD%20t%C3%A1n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Th%C6%B0%C6%A1ng%20nh%C4%A9%20t%E1%BB%AD%20t%C3%A1n%20medicinal%20herb"}]},{"name":"An cung ngưu hoàng hoàn","aliases":["an cung nguu hoang","an gong niu huang wan"],"category":"Bài thuốc cổ truyền","indications":"Bài cổ truyền dùng trong một số tình trạng sốt cao hôn mê theo chỉ định chuyên khoa; không phải thuốc dự phòng đột quỵ.","main":"Công thức có thể chứa ngưu hoàng, chu sa/hùng hoàng hoặc thành phần thay thế tùy sản phẩm; nguy cơ chất lượng và kim loại nặng.","contraindications":"Không tự uống khi nghi đột quỵ; tránh thai kỳ, suy gan/thận và sản phẩm không kiểm nghiệm. Gọi cấp cứu ngay khi có dấu hiệu đột quỵ.","side":"Buồn nôn, dị ứng, tổn thương gan/thận hoặc ngộ độc kim loại nặng tùy sản phẩm.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=An%20cung%20ng%C6%B0u%20ho%C3%A0ng%20ho%C3%A0n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=An%20cung%20ng%C6%B0u%20ho%C3%A0ng%20ho%C3%A0n%20medicinal%20herb"}]},{"name":"Mimosa – phối hợp thảo dược an thần","aliases":["Mimosa"],"category":"Sản phẩm thảo dược","indications":"Sản phẩm phối hợp thảo dược dùng hỗ trợ mất ngủ; thành phần cụ thể phải đối chiếu nhãn.","main":"Thường phối hợp lạc tiên, bình vôi, lá vông, sen hoặc trinh nữ tùy nhà sản xuất.","contraindications":"Tránh lái xe, rượu, thai kỳ và dùng cùng nhiều thuốc an thần.","side":"Buồn ngủ, chóng mặt, hạ huyết áp, rối loạn tiêu hóa.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Mimosa%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c%20an%20th%E1%BA%A7n"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Mimosa%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c%20an%20th%E1%BA%A7n%20medicinal%20herb"}]},{"name":"Hoạt huyết dưỡng não – phối hợp thảo dược","aliases":["Hoạt huyết dưỡng não Traphaco","Cebraton"],"category":"Sản phẩm thảo dược","indications":"Sản phẩm thường dùng hỗ trợ đau đầu, chóng mặt và suy giảm tuần hoàn não; không dùng thay đánh giá đột quỵ.","main":"Thường chứa đinh lăng và bạch quả; công thức/hàm lượng tùy sản phẩm.","contraindications":"Tránh khi chảy máu, trước phẫu thuật, động kinh không kiểm soát hoặc dùng chống đông.","side":"Đau đầu, rối loạn tiêu hóa, dị ứng, tăng chảy máu.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ho%E1%BA%A1t%20huy%E1%BA%BFt%20d%C6%B0%E1%BB%A1ng%20n%C3%A3o%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Ho%E1%BA%A1t%20huy%E1%BA%BFt%20d%C6%B0%E1%BB%A1ng%20n%C3%A3o%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c%20medicinal%20herb"}]},{"name":"Bảo Thanh – siro/viên ngậm thảo dược","aliases":["Bảo Thanh"],"category":"Sản phẩm thảo dược","indications":"Hỗ trợ giảm ho và đau rát họng; thành phần thay đổi theo dạng sản phẩm.","main":"Phối hợp dược liệu long đờm/làm dịu họng như ô mai, mật ong, cát cánh, tỳ bà diệp hoặc tương tự.","contraindications":"Thận trọng đái tháo đường do đường/mật ong, trẻ nhỏ và dị ứng thành phần; khám khi khó thở hoặc sốt kéo dài.","side":"Dị ứng, đầy bụng, tăng đường huyết tùy chế phẩm.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=B%E1%BA%A3o%20Thanh%20%E2%80%93%20siro/vi%C3%AAn%20ng%E1%BA%ADm%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=B%E1%BA%A3o%20Thanh%20%E2%80%93%20siro/vi%C3%AAn%20ng%E1%BA%ADm%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c%20medicinal%20herb"}]},{"name":"Eugica – phối hợp tinh dầu thảo dược","aliases":["Eugica"],"category":"Sản phẩm thảo dược","indications":"Hỗ trợ triệu chứng ho, đau họng và nghẹt mũi nhẹ.","main":"Thường phối hợp tinh dầu khuynh diệp, bạc hà, gừng/tần và các thành phần làm dịu.","contraindications":"Không dùng tinh dầu đậm đặc cho trẻ nhỏ; thận trọng thai kỳ, trào ngược và dị ứng.","side":"Ợ nóng, kích ứng, dị ứng; dùng sai tinh dầu có thể gây co thắt đường thở ở trẻ.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Eugica%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20tinh%20d%E1%BA%A7u%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Eugica%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20tinh%20d%E1%BA%A7u%20th%E1%BA%A3o%20d%C6%B0%E1%BB%A3c%20medicinal%20herb"}]},{"name":"Boganic – phối hợp hỗ trợ gan","aliases":["Boganic"],"category":"Sản phẩm thảo dược","indications":"Sản phẩm phối hợp dược liệu hỗ trợ chức năng gan và khó tiêu; không thay điều trị viêm gan hoặc tắc mật.","main":"Thường phối hợp atisô, rau đắng đất và dược liệu lợi mật khác; đối chiếu đúng nhãn sản phẩm.","contraindications":"Tránh tắc mật/sỏi mật có triệu chứng, bệnh gan cấp chưa chẩn đoán và dị ứng thành phần.","side":"Đầy bụng, tiêu chảy, dị ứng.","interactions":"Tương tác phụ thuộc từng vị và hàm lượng. Cần rà soát thuốc chống đông/kháng tiểu cầu, thuốc hạ áp, hạ đường huyết, an thần, thuốc tim mạch và thuốc chuyển hóa qua gan trước khi phối hợp.","sources":[{"name":"Cục Quản lý Y Dược Cổ Truyền","url":"https://ydct.moh.gov.vn/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Boganic%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20h%E1%BB%97%20tr%E1%BB%A3%20gan"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=Boganic%20%E2%80%93%20ph%E1%BB%91i%20h%E1%BB%A3p%20h%E1%BB%97%20tr%E1%BB%A3%20gan%20medicinal%20herb"}]},{"name":"Vitamin A","aliases":["retinol","beta-carotene vitamin A"],"category":"Thực phẩm bổ sung/TPCN","indications":"Phòng/điều trị thiếu vitamin A; hỗ trợ thị giác, miễn dịch và biểu mô.","main":"Retinoid tham gia chu trình thị giác và điều hòa phiên mã.","contraindications":"Tránh liều cao trong thai kỳ và bệnh gan; không phối hợp nhiều chế phẩm chứa vitamin A/retinoid.","side":"Buồn nôn, đau đầu, khô da, rụng tóc; quá liều mạn gây độc gan và tăng áp lực nội sọ.","interactions":"Tăng độc tính với isotretinoin/acitretin và thuốc độc gan; orlistat/cholestyramine giảm hấp thu.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20A%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin B1","aliases":["thiamine"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu thiamin, beriberi, hỗ trợ bệnh não Wernicke theo đường dùng phù hợp.","main":"Coenzym trong chuyển hóa carbohydrate và dẫn truyền thần kinh.","contraindications":"Dị ứng với chế phẩm; phản vệ hiếm gặp chủ yếu đường tiêm.","side":"Buồn nôn, kích ứng; phản vệ hiếm với tiêm.","interactions":"Ít tương tác; lợi tiểu kéo dài và rượu có thể làm tăng thiếu hụt.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B1%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin B2","aliases":["riboflavin"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu riboflavin; một số phác đồ dùng dự phòng migraine.","main":"Tiền chất FAD/FMN trong phản ứng oxy hóa–khử.","contraindications":"Thận trọng dị ứng; nước tiểu vàng cam là vô hại.","side":"Nước tiểu vàng sáng, tiêu chảy nhẹ.","interactions":"Ít tương tác đáng kể.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B2%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin B3","aliases":["niacin","nicotinamide"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu niacin; niacin liều dược lý từng dùng hạ lipid nhưng cần giám sát.","main":"Tiền chất NAD/NADP; liều cao niacin giảm tổng hợp VLDL.","contraindications":"Tránh bệnh gan hoạt động, loét dạ dày tiến triển, gout không kiểm soát; thận trọng đái tháo đường.","side":"Đỏ bừng, ngứa, tăng men gan, tăng đường huyết/acid uric; độc gan với liều cao.","interactions":"Tăng độc cơ với statin và độc gan với rượu/thuốc độc gan.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B3%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin B5","aliases":["pantothenic acid"],"category":"Thực phẩm bổ sung/TPCN","indications":"Bổ sung khi thiếu hiếm gặp; thường có trong đa vitamin.","main":"Thành phần coenzym A trong chuyển hóa acid béo.","contraindications":"Thận trọng dị ứng; không có chỉ định điều trị rộng đã chứng minh.","side":"Tiêu chảy và khó chịu tiêu hóa khi liều cao.","interactions":"Ít tương tác.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B5%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin B6","aliases":["pyridoxine"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu B6; dự phòng bệnh lý thần kinh do isoniazid; hỗ trợ buồn nôn thai kỳ theo phác đồ.","main":"Coenzym chuyển hóa acid amin và tổng hợp chất dẫn truyền thần kinh.","contraindications":"Không dùng liều cao kéo dài; thận trọng bệnh thần kinh.","side":"Liều cao mạn gây bệnh lý thần kinh cảm giác, mất điều hòa.","interactions":"Giảm tác dụng levodopa nếu không phối hợp carbidopa; penicillamine/isoniazid làm tăng nhu cầu.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B6%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Biotin","aliases":["vitamin B7","vitamin H"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu biotin hiếm gặp; bằng chứng cho tóc/móng ở người không thiếu còn yếu.","main":"Coenzym carboxylase trong chuyển hóa acid béo và glucose.","contraindications":"Ngừng trước xét nghiệm theo hướng dẫn vì biotin liều cao gây sai kết quả.","side":"Thường dung nạp tốt; vấn đề chính là nhiễu xét nghiệm.","interactions":"Gây sai lệch troponin, TSH, hormon và nhiều xét nghiệm miễn dịch.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Biotin%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Acid folic","aliases":["folate","vitamin B9"],"category":"Thực phẩm bổ sung/TPCN","indications":"Phòng dị tật ống thần kinh, điều trị thiếu folate và thiếu máu hồng cầu khổng lồ do thiếu folate.","main":"Tham gia tổng hợp DNA và chuyển hóa một-carbon.","contraindications":"Không điều trị thiếu máu chưa loại trừ thiếu B12 vì có thể che lấp huyết học trong khi tổn thương thần kinh tiến triển.","side":"Buồn nôn, đầy bụng; hiếm dị ứng.","interactions":"Tương tác methotrexate tùy chỉ định, phenytoin và trimethoprim; folinic acid khác folic acid.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Acid%20folic%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin B12","aliases":["cobalamin","cyanocobalamin","methylcobalamin"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu B12 do ăn uống, kém hấp thu hoặc thiếu yếu tố nội; hỗ trợ bệnh lý thần kinh do thiếu B12.","main":"Cofactor tổng hợp DNA và myelin.","contraindications":"Thận trọng bệnh Leber và dị ứng cobalt; đánh giá nguyên nhân thiếu.","side":"Đau tại chỗ tiêm, phát ban; hạ kali hiếm khi điều trị thiếu máu nặng.","interactions":"Metformin và PPI kéo dài giảm hấp thu; chloramphenicol có thể giảm đáp ứng huyết học.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20B12%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin C","aliases":["ascorbic acid"],"category":"Thực phẩm bổ sung/TPCN","indications":"Phòng/điều trị thiếu vitamin C; tăng hấp thu sắt không heme; không ngăn chắc chắn cảm lạnh.","main":"Chống oxy hóa và cofactor tổng hợp collagen/catecholamin.","contraindications":"Thận trọng sỏi oxalat, bệnh thận, thừa sắt và thiếu G6PD khi liều rất cao.","side":"Đau bụng, tiêu chảy; liều cao tăng oxalat niệu.","interactions":"Tăng hấp thu sắt; có thể ảnh hưởng một số xét nghiệm và thuốc hóa trị tùy bối cảnh.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20C%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin D","aliases":["cholecalciferol","ergocalciferol","vitamin D3","vitamin D2"],"category":"Thực phẩm bổ sung/TPCN","indications":"Phòng/điều trị thiếu vitamin D, còi xương/nhuyễn xương; hỗ trợ điều trị loãng xương cùng calci khi phù hợp.","main":"Tăng hấp thu calci/phosphat và điều hòa xương–cơ–miễn dịch.","contraindications":"Tránh tăng calci máu, ngộ độc vitamin D; thận trọng sarcoidosis, sỏi thận và suy thận.","side":"Quá liều gây tăng calci: buồn nôn, khát, tiểu nhiều, lú lẫn, loạn nhịp và tổn thương thận.","interactions":"Thiazide tăng nguy cơ tăng calci; orlistat/cholestyramine giảm hấp thu; steroid giảm tác dụng.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20D%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin E","aliases":["tocopherol"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu vitamin E hiếm gặp; không khuyến cáo liều cao thường quy để phòng tim mạch.","main":"Chống oxy hóa tan trong lipid bảo vệ màng tế bào.","contraindications":"Tránh liều cao khi chảy máu, dùng chống đông hoặc trước phẫu thuật.","side":"Buồn nôn, mệt, tăng nguy cơ chảy máu; liều rất cao có thể tăng nguy cơ biến cố.","interactions":"Tăng nguy cơ chảy máu với warfarin/acenocoumarol, aspirin và clopidogrel.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20E%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Vitamin K","aliases":["phylloquinone","menaquinone","vitamin K1","vitamin K2"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu vitamin K và đảo ngược tác dụng kháng vitamin K theo chỉ định; hỗ trợ xương chưa có bằng chứng đồng nhất.","main":"Cofactor carboxyl hóa các yếu tố đông máu và protein xương.","contraindications":"Không tự bổ sung khi dùng warfarin/acenocoumarol; cần duy trì lượng ăn ổn định.","side":"Phản ứng dị ứng hiếm; đường tiêm có thể gây phản ứng nặng.","interactions":"Đối kháng trực tiếp warfarin và acenocoumarol, làm giảm INR.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Vitamin%20K%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Calci","aliases":["calcium carbonate","calcium citrate"],"category":"Thực phẩm bổ sung/TPCN","indications":"Bổ sung khi khẩu phần thiếu, điều trị hạ calci và hỗ trợ loãng xương cùng vitamin D.","main":"Khoáng chất cho xương, co cơ và dẫn truyền thần kinh.","contraindications":"Tránh tăng calci máu, sỏi calci tái phát hoặc suy thận nặng chưa đánh giá.","side":"Táo bón, đầy bụng; quá liều gây tăng calci và sỏi thận.","interactions":"Giảm hấp thu levothyroxine, tetracycline, quinolone, bisphosphonate và sắt; dùng cách thời gian.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Calci%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Magnesi","aliases":["magnesium oxide","magnesium citrate","magnesium glycinate"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu magnesi; một số muối dùng nhuận tràng hoặc hỗ trợ migraine.","main":"Cofactor enzym, ổn định điện thế màng và chức năng cơ–thần kinh.","contraindications":"Tránh suy thận nặng hoặc block tim nếu chưa giám sát.","side":"Tiêu chảy; quá liều ở suy thận gây yếu cơ, hạ huyết áp, nhịp chậm và ức chế hô hấp.","interactions":"Giảm hấp thu tetracycline, quinolone, bisphosphonate và levothyroxine; dùng cách thời gian.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Magnesi%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Sắt","aliases":["ferrous sulfate","ferrous fumarate","ferrous gluconate"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu sắt và thiếu máu thiếu sắt; cần tìm nguyên nhân mất máu.","main":"Cần cho hemoglobin, myoglobin và enzym oxy hóa.","contraindications":"Tránh quá tải sắt/hemochromatosis, thiếu máu không do thiếu sắt; bảo quản xa trẻ em.","side":"Táo bón, buồn nôn, đau bụng, phân đen; quá liều cấp rất độc.","interactions":"Giảm hấp thu levothyroxine, tetracycline/quinolone, levodopa; antacid giảm hấp thu.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=S%E1%BA%AFt%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Kẽm","aliases":["zinc sulfate","zinc gluconate"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu kẽm; viên ngậm có thể rút ngắn nhẹ cảm lạnh nếu dùng sớm.","main":"Cofactor nhiều enzym, miễn dịch và lành vết thương.","contraindications":"Không dùng liều cao kéo dài; tránh xịt mũi kẽm do nguy cơ mất ngửi.","side":"Buồn nôn, vị kim loại; liều cao gây thiếu đồng và giảm miễn dịch.","interactions":"Giảm hấp thu tetracycline/quinolone và penicillamine; dùng cách thời gian.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=K%E1%BA%BDm%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Selen","aliases":["selenium"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu selen hiếm gặp; không dùng liều cao để phòng ung thư.","main":"Thành phần selenoprotein chống oxy hóa và chuyển hóa hormon giáp.","contraindications":"Tránh liều cao và bệnh thận/gan chưa đánh giá.","side":"Quá liều gây mùi tỏi, rụng tóc, móng giòn, tổn thương thần kinh và tiêu hóa.","interactions":"Có thể ảnh hưởng thuốc tuyến giáp và hóa trị; dữ liệu tương tác tùy liều.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Selen%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Iod","aliases":["iodine","potassium iodide"],"category":"Thực phẩm bổ sung/TPCN","indications":"Phòng/điều trị thiếu iod; potassium iodide dùng bảo vệ tuyến giáp trong phơi nhiễm iod phóng xạ theo hướng dẫn.","main":"Nguyên liệu tổng hợp hormon tuyến giáp.","contraindications":"Thận trọng bệnh tuyến giáp tự miễn, bướu đa nhân, dị ứng chế phẩm iod và thuốc gây rối loạn kali.","side":"Vị kim loại, đau tuyến nước bọt, phát ban; thừa iod gây cường hoặc suy giáp.","interactions":"Tương tác amiodarone, lithium, thuốc kháng giáp và ACEI/ARB với potassium iodide.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Iod%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Omega-3","aliases":["fish oil","EPA","DHA","dầu cá"],"category":"Thực phẩm bổ sung/TPCN","indications":"Giảm triglycerid ở liều kê đơn; bổ sung dinh dưỡng khi ăn ít cá.","main":"EPA/DHA giảm tổng hợp VLDL, điều hòa viêm và màng tế bào.","contraindications":"Thận trọng dị ứng cá, chảy máu, rung nhĩ và trước phẫu thuật khi dùng liều cao.","side":"Ợ tanh, khó tiêu; liều cao tăng chảy máu và có thể tăng nguy cơ rung nhĩ.","interactions":"Cộng hợp thuốc chống đông/kháng tiểu cầu và thuốc hạ áp.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Omega-3%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Glucosamine","aliases":["glucosamine sulfate","glucosamine hydrochloride"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể giảm nhẹ đau thoái hóa khớp ở một số người; hiệu quả không đồng nhất.","main":"Tiền chất glycosaminoglycan của sụn; tác dụng chống viêm nhẹ.","contraindications":"Thận trọng dị ứng hải sản tùy nguồn, đái tháo đường, glaucoma và dùng warfarin.","side":"Đầy bụng, buồn nôn, táo bón/tiêu chảy.","interactions":"Có báo cáo tăng INR với warfarin; theo dõi đường huyết.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Glucosamine%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Chondroitin","aliases":["chondroitin sulfate"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể hỗ trợ triệu chứng thoái hóa khớp, thường phối hợp glucosamine.","main":"Glycosaminoglycan của sụn, có thể giảm thoái hóa nền ngoại bào.","contraindications":"Thận trọng chảy máu, hen và sản phẩm nguồn động vật không rõ chất lượng.","side":"Rối loạn tiêu hóa, phù, dị ứng.","interactions":"Có thể tăng chảy máu với thuốc chống đông/kháng tiểu cầu.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Chondroitin%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Collagen peptide","aliases":["hydrolyzed collagen","collagen"],"category":"Thực phẩm bổ sung/TPCN","indications":"Bổ sung protein; có thể hỗ trợ nhẹ đau khớp và độ ẩm da sau vài tháng.","main":"Cung cấp peptide giàu glycin/prolin cho mô liên kết; bằng chứng phụ thuộc sản phẩm.","contraindications":"Thận trọng dị ứng nguồn cá/bò/gà và bệnh thận cần hạn chế protein.","side":"Đầy bụng, vị khó chịu, dị ứng.","interactions":"Ít tương tác; chú ý thành phần bổ sung đi kèm.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Collagen%20peptide%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Coenzyme Q10","aliases":["CoQ10","ubiquinone","ubiquinol"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể hỗ trợ một số triệu chứng suy tim hoặc đau cơ liên quan statin; bằng chứng không đồng nhất.","main":"Thành phần chuỗi hô hấp ty thể và chất chống oxy hóa.","contraindications":"Thận trọng huyết áp thấp, thai kỳ và dùng chống đông.","side":"Khó chịu tiêu hóa, mất ngủ, hạ huyết áp.","interactions":"Có thể giảm tác dụng warfarin do cấu trúc giống vitamin K; cộng hợp thuốc hạ áp.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Coenzyme%20Q10%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Probiotic","aliases":["men vi sinh","Lactobacillus","Bifidobacterium"],"category":"Thực phẩm bổ sung/TPCN","indications":"Một số chủng giúp phòng tiêu chảy do kháng sinh và hỗ trợ IBS; hiệu quả phụ thuộc chính xác chủng/liều.","main":"Vi sinh vật sống ảnh hưởng hệ vi sinh, hàng rào ruột và miễn dịch.","contraindications":"Thận trọng suy giảm miễn dịch nặng, catheter tĩnh mạch trung tâm, viêm tụy nặng hoặc trẻ sinh non.","side":"Đầy hơi; hiếm nhiễm khuẩn huyết/nấm huyết ở người nguy cơ cao.","interactions":"Kháng sinh có thể giảm hiệu quả; dùng cách vài giờ. Thuốc ức chế miễn dịch tăng nguy cơ nhiễm trùng.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Probiotic%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Prebiotic","aliases":["inulin","FOS","GOS"],"category":"Thực phẩm bổ sung/TPCN","indications":"Chất xơ lên men hỗ trợ hệ vi sinh và táo bón nhẹ.","main":"Được vi khuẩn ruột lên men tạo acid béo chuỗi ngắn.","contraindications":"Thận trọng IBS/FODMAP, tắc ruột hoặc đầy hơi nặng.","side":"Đầy hơi, đau quặn, tiêu chảy.","interactions":"Có thể thay đổi hấp thu thuốc do tăng nhu động; dùng cách thuốc nếu cần.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Prebiotic%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Melatonin","aliases":["melatonin supplement"],"category":"Thực phẩm bổ sung/TPCN","indications":"Hỗ trợ lệch múi giờ và một số rối loạn nhịp ngủ; hiệu quả tùy thời điểm dùng.","main":"Hormon tuyến tùng điều hòa nhịp sinh học qua thụ thể MT1/MT2.","contraindications":"Thận trọng thai kỳ, bệnh tự miễn, động kinh, dùng chống đông, hạ đường huyết hoặc thuốc an thần.","side":"Buồn ngủ ban ngày, đau đầu, chóng mặt, giấc mơ sống động.","interactions":"Cộng hợp thuốc an thần/rượu; có thể ảnh hưởng warfarin, fluvoxamine và thuốc hạ đường huyết.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Melatonin%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Creatine monohydrate","aliases":["creatine"],"category":"Thực phẩm bổ sung/TPCN","indications":"Tăng sức mạnh và khối cơ khi kết hợp tập kháng lực; hỗ trợ một số bệnh cơ theo chỉ định.","main":"Tăng dự trữ phosphocreatine để tái tạo ATP nhanh.","contraindications":"Thận trọng bệnh thận, mất nước và sản phẩm không tinh khiết.","side":"Tăng cân do nước, đầy bụng, chuột rút; creatinine máu có thể tăng không phản ánh giảm GFR.","interactions":"NSAID/thuốc độc thận và mất nước có thể tăng nguy cơ thận.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Creatine%20monohydrate%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Whey protein","aliases":["protein whey","đạm whey"],"category":"Thực phẩm bổ sung/TPCN","indications":"Bổ sung protein khi khẩu phần không đủ, hỗ trợ phục hồi và tăng cơ.","main":"Cung cấp acid amin thiết yếu và leucine kích hoạt tổng hợp protein cơ.","contraindications":"Tránh dị ứng sữa; thận trọng không dung nạp lactose, bệnh thận/gan cần hạn chế protein.","side":"Đầy bụng, tiêu chảy, dị ứng.","interactions":"Có thể giảm hấp thu levodopa do cạnh tranh acid amin; chú ý đường/chất kích thích trong sản phẩm.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Whey%20protein%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"L-carnitine","aliases":["levocarnitine"],"category":"Thực phẩm bổ sung/TPCN","indications":"Điều trị thiếu carnitine; bằng chứng giảm cân hoặc tăng hiệu suất ở người bình thường hạn chế.","main":"Vận chuyển acid béo dài vào ty thể để beta-oxy hóa.","contraindications":"Thận trọng động kinh, suy giáp và dùng warfarin.","side":"Buồn nôn, tiêu chảy, mùi cơ thể tanh; có thể tăng co giật.","interactions":"Có báo cáo tăng INR với warfarin; có thể đối kháng hormon giáp.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=L-carnitine%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Alpha-lipoic acid","aliases":["ALA supplement","thioctic acid"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể hỗ trợ đau thần kinh do đái tháo đường; bằng chứng cho giảm cân hạn chế.","main":"Cofactor ty thể và chất chống oxy hóa tái sinh vitamin C/E.","contraindications":"Thận trọng hạ đường huyết, thiếu thiamin do rượu và bệnh tuyến giáp.","side":"Buồn nôn, phát ban, hạ đường huyết; hiếm hội chứng insulin tự miễn.","interactions":"Cộng hợp thuốc hạ đường huyết; có thể giảm hiệu quả thuốc tuyến giáp/kim loại nếu uống cùng.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Alpha-lipoic%20acid%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Lutein + Zeaxanthin","aliases":["lutein","zeaxanthin"],"category":"Thực phẩm bổ sung/TPCN","indications":"Bổ sung carotenoid hoàng điểm; công thức AREDS2 giảm nguy cơ tiến triển AMD ở nhóm phù hợp.","main":"Tập trung tại hoàng điểm, lọc ánh sáng xanh và chống oxy hóa.","contraindications":"Không thay khám mắt; thận trọng hút thuốc nếu sản phẩm chứa beta-carotene.","side":"Da vàng nhẹ, khó chịu tiêu hóa.","interactions":"Ít tương tác; chất béo tăng hấp thu.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Lutein%20%2B%20Zeaxanthin%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Resveratrol","aliases":["resveratrol supplement"],"category":"Thực phẩm bổ sung/TPCN","indications":"Được quảng bá chống oxy hóa/tim mạch nhưng bằng chứng lâm sàng chưa đủ cho phòng bệnh.","main":"Polyphenol điều hòa sirtuin và tín hiệu viêm trong nghiên cứu.","contraindications":"Tránh chảy máu, ung thư nhạy cảm hormon, thai kỳ hoặc trước phẫu thuật.","side":"Tiêu chảy, đau đầu, tăng men gan; có thể tăng chảy máu.","interactions":"Tương tác chống đông/kháng tiểu cầu và enzym CYP.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Resveratrol%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Berberine","aliases":["berberin supplement","berberis"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể giảm đường huyết và lipid ở mức vừa; chất lượng chế phẩm và tương tác là vấn đề.","main":"Hoạt hóa AMPK, ảnh hưởng hệ vi sinh và ức chế CYP/P-gp.","contraindications":"Tránh thai kỳ, cho con bú, trẻ sơ sinh, bệnh gan nặng và phối hợp thuốc có khoảng điều trị hẹp.","side":"Táo bón, đau bụng, buồn nôn, hạ đường huyết/huyết áp.","interactions":"Tương tác cyclosporin/tacrolimus, thuốc hạ đường huyết, chống đông, chống loạn nhịp và nhiều thuốc CYP/P-gp.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Berberine%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"N-acetylcysteine","aliases":["NAC","acetylcysteine supplement"],"category":"Thực phẩm bổ sung/TPCN","indications":"Thuốc giải độc paracetamol và tiêu nhầy theo chỉ định; dạng bổ sung được dùng chống oxy hóa nhưng không thay điều trị.","main":"Tiền chất glutathione và phá cầu disulfide của mucoprotein.","contraindications":"Thận trọng hen, loét dạ dày và dùng nitroglycerin.","side":"Buồn nôn, nôn, tiêu chảy; co thắt phế quản hiếm; phản vệ giả với đường tĩnh mạch.","interactions":"Tăng đau đầu/hạ áp với nitroglycerin; than hoạt có thể giảm hấp thu đường uống.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=N-acetylcysteine%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Ginkgo supplement","aliases":["ginkgo extract","EGb 761"],"category":"Thực phẩm bổ sung/TPCN","indications":"Hỗ trợ một số triệu chứng nhận thức/tuần hoàn; không phòng hoặc điều trị cấp đột quỵ.","main":"Chiết xuất chuẩn hóa flavonoid và terpene lacton ảnh hưởng vi tuần hoàn và tiểu cầu.","contraindications":"Tránh chảy máu, động kinh, trước phẫu thuật và thuốc chống đông.","side":"Đau đầu, chóng mặt, rối loạn tiêu hóa, chảy máu.","interactions":"Tăng chảy máu và có thể giảm ngưỡng co giật.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ginkgo%20supplement%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Milk thistle","aliases":["Silybum marianum","silymarin","kế sữa"],"category":"Thực phẩm bổ sung/TPCN","indications":"Dùng hỗ trợ chức năng gan; bằng chứng trong viêm gan/xơ gan còn không nhất quán.","main":"Silymarin chống oxy hóa và ổn định màng tế bào gan trong nghiên cứu.","contraindications":"Thận trọng dị ứng họ Cúc, ung thư nhạy cảm hormon và bệnh gan nặng.","side":"Đầy bụng, tiêu chảy, dị ứng.","interactions":"Có thể ảnh hưởng CYP và đường huyết; dữ liệu lâm sàng tương tác còn hạn chế.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Milk%20thistle%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Cranberry","aliases":["cranberry extract","nam việt quất"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể giảm tái phát UTI ở một số nhóm; không điều trị UTI đang có.","main":"Proanthocyanidin giảm bám dính E. coli lên niệu mạc.","contraindications":"Thận trọng sỏi oxalat, warfarin và triệu chứng UTI có sốt/đau hông.","side":"Đau bụng, tiêu chảy; có thể tăng oxalat niệu.","interactions":"Có báo cáo tăng INR với warfarin; theo dõi nếu dùng thường xuyên.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Cranberry%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Ashwagandha","aliases":["Withania somnifera","sâm Ấn Độ"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể hỗ trợ stress, lo âu và giấc ngủ ngắn hạn; dữ liệu dài hạn hạn chế.","main":"Withanolide ảnh hưởng trục stress, GABA và miễn dịch.","contraindications":"Tránh thai kỳ, bệnh tự miễn, cường giáp, bệnh gan và dùng thuốc an thần/ức chế miễn dịch.","side":"Buồn ngủ, tiêu chảy; đã có báo cáo tổn thương gan và tăng hormon giáp.","interactions":"Cộng hợp thuốc an thần, hạ đường huyết/hạ áp, hormon giáp và ức chế miễn dịch.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ashwagandha%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Rhodiola rosea","aliases":["rhodiola","golden root"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể hỗ trợ mệt mỏi do stress; bằng chứng chưa đồng nhất.","main":"Rosavin/salidroside ảnh hưởng monoamine và đáp ứng stress.","contraindications":"Thận trọng rối loạn lưỡng cực, mất ngủ, thai kỳ và thuốc hướng thần.","side":"Kích thích, mất ngủ, chóng mặt, khô miệng.","interactions":"Có thể tương tác thuốc chống trầm cảm, kích thích và hạ đường huyết.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Rhodiola%20rosea%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Echinacea","aliases":["Echinacea purpurea"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể rút ngắn nhẹ cảm lạnh ở một số chế phẩm; không phòng chắc chắn.","main":"Alkylamide và polysaccharid điều hòa miễn dịch.","contraindications":"Tránh dị ứng họ Cúc, bệnh tự miễn, ghép tạng và dùng ức chế miễn dịch.","side":"Dị ứng, buồn nôn, phát ban; hiếm phản vệ.","interactions":"Có thể đối kháng thuốc ức chế miễn dịch và ảnh hưởng CYP.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Echinacea%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Saw palmetto","aliases":["Serenoa repens"],"category":"Thực phẩm bổ sung/TPCN","indications":"Được dùng cho triệu chứng đường tiểu do phì đại tiền liệt tuyến nhưng lợi ích trong nghiên cứu lớn hạn chế.","main":"Acid béo/phytosterol có thể ức chế 5-alpha-reductase nhẹ.","contraindications":"Không dùng thay đánh giá bí tiểu, tiểu máu hoặc ung thư tuyến tiền liệt; thận trọng chống đông.","side":"Đau bụng, đau đầu, giảm libido; tăng chảy máu hiếm.","interactions":"Có thể cộng hợp thuốc chống đông và thuốc nội tiết.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Saw%20palmetto%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Evening primrose oil","aliases":["dầu hoa anh thảo","GLA"],"category":"Thực phẩm bổ sung/TPCN","indications":"Được dùng cho đau vú, eczema và triệu chứng tiền kinh; bằng chứng không ổn định.","main":"Cung cấp gamma-linolenic acid, tiền chất eicosanoid.","contraindications":"Tránh động kinh, rối loạn chảy máu, thai kỳ và trước phẫu thuật.","side":"Đau bụng, tiêu chảy, đau đầu; có thể tăng co giật/chảy máu.","interactions":"Tương tác phenothiazine, thuốc chống co giật và chống đông.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=Evening%20primrose%20oil%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"St. John’s wort","aliases":["Hypericum perforatum","cỏ ban âu"],"category":"Thực phẩm bổ sung/TPCN","indications":"Có thể hiệu quả trong trầm cảm nhẹ–vừa nhưng tương tác thuốc cực nhiều; không dùng cho trầm cảm nặng/tự sát.","main":"Hyperforin/hypericin ảnh hưởng monoamine và cảm ứng CYP3A4/P-gp.","contraindications":"Tránh thai kỳ, rối loạn lưỡng cực, ghép tạng, HIV, ung thư, thuốc tránh thai và nhiều thuốc kê đơn.","side":"Nhạy cảm ánh sáng, mất ngủ, kích động; hội chứng serotonin khi phối hợp.","interactions":"Giảm nồng độ cyclosporin, tacrolimus, thuốc tránh thai, thuốc HIV, chống đông, chống ung thư; tăng serotonin với SSRI/SNRI/MAOI.","sources":[{"name":"NIH ODS","url":"https://ods.od.nih.gov/factsheets/list-all/"},{"name":"DSLD – NIH","url":"https://dsld.od.nih.gov/"},{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=St.%20John%E2%80%99s%20wort%20supplement"},{"name":"Cục An toàn thực phẩm","url":"https://vfa.gov.vn/"}]},{"name":"Tofisopam","aliases":["Grandaxin","Emandaxin","Sériel"],"category":"Thuốc giải lo âu","indications":"Điều trị triệu chứng lo âu, căng thẳng thần kinh và một số biểu hiện cơ thể liên quan đến lo âu. Ở một số quốc gia, thuốc còn được dùng hỗ trợ trong hội chứng cai rượu. Chỉ dùng theo chỉ định của bác sĩ vì phạm vi chỉ định và tình trạng lưu hành khác nhau giữa các nước.","main":"Tofisopam là dẫn chất 2,3-benzodiazepin có tác dụng giải lo âu nhưng khác các benzodiazepin cổ điển: thường ít gây an thần, ít làm giãn cơ, ít ảnh hưởng trí nhớ và phối hợp vận động. Cơ chế chính xác chưa được xác định đầy đủ; thuốc không được xem là thuốc chống co giật điển hình.","contraindications":"Không dùng khi dị ứng với tofisopam hoặc thành phần thuốc. Thận trọng ở người suy hô hấp nặng, suy gan hoặc suy thận, động kinh, glaucoma góc đóng, người cao tuổi, phụ nữ mang thai hoặc cho con bú. Không tự dùng chung với rượu hay thuốc tác động thần kinh trung ương. Cần kiểm tra tờ hướng dẫn của đúng sản phẩm vì chống chỉ định có thể khác theo quốc gia.","side":"Có thể gặp mất ngủ, kích thích, bồn chồn, đau đầu, chóng mặt, buồn nôn, táo bón, khô miệng hoặc phát ban. Hiếm gặp phản ứng dị ứng, lú lẫn, co giật hoặc bất thường chức năng gan. Ngừng thuốc và đi khám ngay khi khó thở, sưng mặt, phát ban nặng, co giật hoặc thay đổi hành vi rõ rệt.","interactions":"Có thể tương tác với thuốc chuyển hóa qua gan, đặc biệt các thuốc ảnh hưởng enzym CYP3A4. Thuốc ức chế CYP3A4 có thể làm tăng nồng độ tofisopam; thuốc cảm ứng enzym có thể làm giảm hiệu quả. Thận trọng khi dùng cùng thuốc an thần, opioid, thuốc ngủ, thuốc chống trầm cảm, thuốc chống loạn thần, thuốc chống đông hoặc rượu. Cần cung cấp đầy đủ danh sách thuốc và thực phẩm bổ sung cho bác sĩ/dược sĩ.","sources":[{"name":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/?term=tofisopam"},{"name":"Google Scholar","url":"https://scholar.google.com/scholar?q=tofisopam"}]}]);
